INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C1','math',2,2,'u3',2,'1 m 알기 — 100 cm가 1 m임을 알고, 1 m를 쓰고 「1 미터」로 읽으며, 몇백 cm와 몇 m를 서로 바꾸기',ARRAY['2수03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C2','math',2,2,'u3',2,'길이를 두 가지로 나타내기 — 몇 cm를 몇 m 몇 cm로 가르고, 몇 m 몇 cm를 몇 cm로 모으며(cm가 한 자리면 0으로 자리 지키기), 단위가 다른 두 길이를 같은 단위로 바꾸어 견주기',ARRAY['2수03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C3','math',2,2,'u3',2,'알맞은 단위 고르기 — 짧은 길이는 cm로, 긴 길이는 m로 나타내면 편함을 알고 상황에 알맞은 단위 고르기',ARRAY['2수03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C4','math',2,2,'u3',3,'줄자로 길이 재기 — 물건에 알맞은 자(곧은자·줄자)를 고르고, 한끝을 눈금 0에 맞추어 다른 끝의 눈금을 읽으며, 잰 길이를 몇 cm와 몇 m 몇 cm로 나타내기',ARRAY['2수03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C5','math',2,2,'u3',4,'길이의 합 — 색 테이프를 이어 붙이는 상황에서 m는 m끼리, cm는 cm끼리 더해 길이의 합을 구하고, 같은 단위끼리 맞추어 세로셈으로 쓰기',ARRAY['2수03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C6','math',2,2,'u3',5,'길이의 차 — 잘라 쓰고 남은 길이·두 도막·두 길이의 차를 m는 m끼리, cm는 cm끼리 빼서 구하고, 구한 차에 뺀 길이를 더해 다시 확인하기',ARRAY['2수03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C7','math',2,2,'u3',6,'1 m를 기준으로 어림하기 — 양팔·뼘·걸음 등 몸의 부분으로 1 m를 재어 보고, 1 m를 기준 삼아 2 m·3 m를 어림하며, 어림한 길이에 「약」을 붙이고 자로 재어 확인하기',ARRAY['2수03-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C8','math',2,2,'u3',7,'긴 거리 어림하기 — 5 m·10 m를 기준 삼거나, 몇 부분으로 나누어 어림한 뒤 더하거나, 같은 간격이 몇 개인지 세어 긴 거리를 어림하기',ARRAY['2수03-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C9','math',2,2,'u3',9,'길이 재기로 문제 해결하기 — 동물 몸길이 사전을 만들며 몸길이를 견주고 합과 차를 구하며, 조사한 길이를 몇 m 몇 cm로 바르게 적기',ARRAY['2수03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X01','math',2,'u3',ARRAY['M2-2-u3-C1','M2-2-u3-C2','M2-2-u3-C4']::text[],'1 m와 100 cm의 관계를 모른다 — 1 m를 10 cm나 1000 cm로 여기거나, 수는 그대로 두고 단위 글자만 바꿔 쓴다(300 cm = 300 m)','1 m 막대에 1 cm가 100번 들어간다 — 100 cm마다 1 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X02','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4']::text[],'몇 m 몇 cm를 몇 cm로 바꿀 때 두 수를 그냥 이어 붙여 0을 빠뜨리거나(3 m 4 cm → 34 cm), m와 cm의 수를 뒤바꾼다','m 자리는 백의 자리 — cm가 한 자리면 십의 자리에 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X03','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4','M2-2-u3-C9']::text[],'몇 cm를 몇 m 몇 cm로 가를 때 자리를 잘못 가른다(248 cm → 24 m 8 cm)','백의 자리 숫자만 m — 뒤의 두 자리는 cm') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X04','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5']::text[],'m의 수와 cm의 수를 더해 버리거나 m와 cm를 한꺼번에 계산한다(5 m 73 cm → 78 cm)','m는 m끼리, cm는 cm끼리 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X05','math',2,'u3',ARRAY['M2-2-u3-C3','M2-2-u3-C9']::text[],'길이에 알맞지 않은 단위를 고르거나 단위를 빠뜨린다(필통 약 15 m, 몸길이 「약 240」)','손에 쥐는 것은 cm, 몸보다 긴 것은 m — 수 뒤에 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X06','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'줄자의 한끝을 0에 맞추지 않거나, 0이 아닌 곳에서 시작했는데 다른 끝의 눈금 숫자를 그대로 길이로 읽는다','한끝을 0에 — 아니면 끝 눈금에서 시작 눈금을 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X07','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'줄자의 눈금을 이웃 눈금으로 잘못 읽는다(140 대신 139·141)','물건 끝에서 줄자까지 선을 내려 긋고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X08','math',2,'u3',ARRAY['M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C9']::text[],'m끼리·cm끼리 계산하면서 한 자리를 잘못 센다(1 m·10 cm 차이)','m 자리, cm 자리를 따로 한 번 더 셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X09','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5','M2-2-u3-C6']::text[],'cm가 한 자리 수일 때 자리를 맞추지 않고 몇십으로 본다(7 m 5 cm의 5를 50처럼 계산)','세로셈에서 cm 수의 일의 자리끼리 줄 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X10','math',2,'u3',ARRAY['M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C9']::text[],'더해야 할 때 빼거나 빼야 할 때 더한다 — 이어 붙인 길이·남은 길이·다른 도막 상황을 거꾸로 읽는다','「이어 붙이면」은 합, 「남은·다른 도막·차」는 차') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X11','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5','M2-2-u3-C6']::text[],'cm의 끝자리 0을 떼고 쓴다(70 cm → 7 cm, 2 m 40 cm → 2 m 4 cm)','cm 자리는 두 자리 — 0도 자리를 지킨다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X12','math',2,'u3',ARRAY['M2-2-u3-C7','M2-2-u3-C8']::text[],'어림한 길이에 「약」을 빼거나, 어림한 길이는 잰 길이와 반드시 같아야 한다고 여긴다','짐작한 길이 앞에는 「약」 — 잰 길이와 조금 달라도 괜찮다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X13','math',2,'u3',ARRAY['M2-2-u3-C7']::text[],'몸의 부분으로 잴 때 단위가 클수록 잰 횟수가 많다고 여기거나, 사람마다 잰 횟수가 같다고 여긴다','큰 걸음은 적게, 작은 뼘은 많이 — 사람마다 크기가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X14','math',2,'u3',ARRAY['M2-2-u3-C7','M2-2-u3-C8']::text[],'기준 길이를 늘려 어림하거나 나누어 어림한 뒤 더할 때 배수·합을 잘못 구한다(약 5 m의 두 배를 약 7 m로, 기준과 횟수를 더함)','기준이 몇 번인지 세어 그만큼 여러 번 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X15','math',2,'u3',ARRAY['M2-2-u3-C8']::text[],'줄 선 사람·놓인 물건의 수와 그 사이 간격의 수를 같다고 여긴다(8명이 1 m 간격 → 8 m)','맨 앞과 맨 뒤 사이의 간격만 세기 — 사람 수보다 하나 적다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X16','math',2,'u3',ARRAY['M2-2-u3-C1','M2-2-u3-C2','M2-2-u3-C3','M2-2-u3-C4','M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C7','M2-2-u3-C8','M2-2-u3-C9']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른, 긴↔짧은','물음의 「아닌·잘못된·짧은」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X17','math',2,'u3',ARRAY['M2-2-u3-C3','M2-2-u3-C7','M2-2-u3-C8']::text[],'길이에 대한 양감이 없어 터무니없는 길이로 어림한다(칠판의 긴 쪽 약 3 cm, 연필 약 1 m)','1 cm는 손톱 너비, 1 m는 양팔 — 떠올려 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X18','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4','M2-2-u3-C7','M2-2-u3-C9']::text[],'단위가 다른 두 길이를 같은 단위로 바꾸지 않고 보이는 수만 견준다(130 cm > 1 m 50 cm)','둘 다 cm로 바꾼 뒤 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X19','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'곧은자와 줄자의 쓰임을 모른다 — 1 m보다 긴 것이나 둥근 것을 곧은자로 재려 하거나 줄자를 구부려 곧은 길이를 잰다','짧고 곧으면 곧은자, 길거나 둥글면 줄자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X20','math',2,'u3',ARRAY['M2-2-u3-C4','M2-2-u3-C8']::text[],'줄자를 팽팽하고 곧게 펴지 않거나, 굽은 길·굴러간 곳까지 따라 재어 직선거리보다 길게 잰다(멀리 던지기에서 떨어진 곳이 아니라 멈춘 곳까지 잼)','줄자는 팽팽하게 곧게 — 출발선에서 떨어진 곳까지 곧은 선으로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X21','math',2,'u3',ARRAY['M2-2-u3-C7']::text[],'몸의 부분으로 잴 때 단위(걸음 폭·뼘)를 일정하게 하지 않아도 된다고 여긴다 — 걸음마다 폭이 달라도 같은 한 걸음으로 센다','한 걸음은 양발을 모은 상태에서 한 발을 옮기고 나머지 발을 따라 모으기 — 매번 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#1','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','「알고 있어요」 — 자의 큰 눈금 한 칸은 1 cm예요. 연필의 한끝이 눈금 0에 맞춰져 있어요. 연필의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X07','M2-2-u3-X05']::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"「알고 있어요」 — 자의 큰 눈금 한 칸은 1 cm예요. 연필의 한끝이 눈금 0에 맞춰져 있어요. 연필의 길이는 몇 cm인가요?","options":[{"t":"8 cm","correct":true},{"t":"9 cm","mis":"M2-2-u3-X07"},{"t":"8 m","mis":"M2-2-u3-X05"}],"explanation":["연필의 한끝이 눈금 0에 있어요.","다른 끝이 눈금 8에 닿았으니 1 cm가 8번 — 8 cm예요.","1 cm는 「1 센티미터」라고 읽어요."],"asset":{"type":"ruler","len":8,"label":"연필"},"variant_rule":{"alt":[{"stem":"「알고 있어요」 — 연필이 눈금 1에서 시작해 눈금 8에서 끝나요. 연필의 길이는 몇 cm인가요?","options":[{"t":"7 cm","correct":true},{"t":"8 cm","mis":"M2-2-u3-X06"},{"t":"9 cm","mis":"M2-2-u3-X06"}],"explanation":["연필의 한끝이 눈금 0이 아니라 눈금 1에 있어요.","1부터 8까지 1 cm가 7번 — 7 cm예요.","끝 눈금 8을 그대로 읽으면 안 돼요."],"asset":{"type":"ruler","len":7,"label":"연필","s":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#2','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','미술관의 큐레이터가 「이 그림의 긴 쪽의 길이는 600 cm예요.」라고 했어요. 600 cm는 1 cm로 몇 번인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"미술관의 큐레이터가 「이 그림의 긴 쪽의 길이는 600 cm예요.」라고 했어요. 600 cm는 1 cm로 몇 번인가요?","options":[{"t":"600번","correct":true},{"t":"6번","mis":"M2-2-u3-X01"},{"t":"60번","mis":"M2-2-u3-X01"}],"explanation":["1 cm가 100번이면 100 cm예요.","600 cm는 1 cm가 600번 — 바닥에 1 cm씩 600번 재어야 해요.","그래서 cm로 나타내면 수가 너무 커서 더 큰 단위가 필요해요."],"variant_rule":{"alt":[{"stem":"미술관의 조각상 높이는 120 cm예요. 120 cm는 1 cm로 몇 번인가요?","options":[{"t":"120번","correct":true},{"t":"12번","mis":"M2-2-u3-X01"},{"t":"1200번","mis":"M2-2-u3-X01"}],"explanation":["1 cm가 10번이면 10 cm, 100번이면 100 cm예요.","120 cm는 1 cm가 120번이에요.","10 cm 자로 재면 12번 — 1 cm 자로는 120번이나 재야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#3','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','100 cm는 1 m와 같아요. 1 m를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X05']::text[],true,'{"seq":3,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"100 cm는 1 m와 같아요. 1 m를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 미터","correct":true},{"t":"1 센티미터","mis":"M2-2-u3-X01"},{"t":"1 엠","mis":"M2-2-u3-X05"}],"explanation":["m는 「미터」라고 읽어요.","cm는 「센티미터」라고 읽어요.","그래서 1 m는 「1 미터」예요."],"variant_rule":{"alt":[{"stem":"수찬이의 키 1 m 20 cm를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 미터 20 센티미터","correct":true},{"t":"120 미터","mis":"M2-2-u3-X01"},{"t":"1 센티미터 20 미터","mis":"M2-2-u3-X02"}],"explanation":["m는 「미터」, cm는 「센티미터」라고 읽어요.","앞의 1은 m, 뒤의 20은 cm예요.","그래서 「1 미터 20 센티미터」라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#4','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'sa','auto','200 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"200 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","200 cm는 100 cm가 2번이에요.","그래서 200 cm = 2 m예요."],"answer":["2"],"variant_rule":{"alt":[{"stem":"600 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","600 cm는 100 cm가 6번이에요.","그래서 600 cm = 6 m예요."],"answer":["6"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#5','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',2,'mc','auto','3 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":5,"concept":"M2-2-u3-C1","difficulty":2,"kind":"mc","stem":"3 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번이에요.","그래서 3 m = 300 cm예요."],"options":[{"t":"300 cm","correct":true},{"t":"30 cm","mis":"M2-2-u3-X01"},{"t":"3000 cm","mis":"M2-2-u3-X01"}],"variant_rule":{"alt":[{"stem":"2 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","2 m는 100 cm가 2번이에요.","그래서 2 m = 200 cm예요."],"options":[{"t":"200 cm","correct":true},{"t":"20 cm","mis":"M2-2-u3-X01"},{"t":"2000 cm","mis":"M2-2-u3-X01"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#6','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'sa','auto','수찬이의 키는 120 cm예요. 수찬이의 키는 1 m보다 몇 cm 더 큰가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u3-C2","difficulty":2,"kind":"sa","stem":"수찬이의 키는 120 cm예요. 수찬이의 키는 1 m보다 몇 cm 더 큰가요? 숫자로 쓰세요.","answer":["20"],"explanation":["1 m는 100 cm예요.","120 cm는 100 cm와 20 cm로 가를 수 있어요.","그래서 1 m보다 20 cm 더 커요 — 1 m 20 cm라고도 써요."],"variant_rule":{"alt":[{"stem":"선생님 책상의 길이는 180 cm예요. 1 m보다 몇 cm 더 긴가요? 숫자로 쓰세요.","answer":["80"],"explanation":["1 m는 100 cm예요.","180 cm는 100 cm와 80 cm로 가를 수 있어요.","그래서 1 m보다 80 cm 더 길어요 — 1 m 80 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#7','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'sa','auto','5 m 73 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C2","difficulty":2,"kind":"sa","stem":"5 m 73 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["5 m는 500 cm예요.","500 cm와 73 cm를 모으면 573 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"answer":["573"],"variant_rule":{"alt":[{"stem":"7 m 16 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["7 m는 700 cm예요.","700 cm와 16 cm를 모으면 716 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"answer":["716"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#8','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'mc','auto','405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":8,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["405 cm는 400 cm와 5 cm예요.","400 cm는 4 m예요.","그래서 405 cm = 4 m 5 cm예요."],"options":[{"t":"4 m 5 cm","correct":true},{"t":"40 m 5 cm","mis":"M2-2-u3-X03"},{"t":"4 m 50 cm","mis":"M2-2-u3-X09"},{"t":"5 m 4 cm","mis":"M2-2-u3-X02"}],"variant_rule":{"alt":[{"stem":"716 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["716 cm는 700 cm와 16 cm예요.","700 cm는 7 m예요.","그래서 716 cm = 7 m 16 cm예요."],"options":[{"t":"7 m 16 cm","correct":true},{"t":"71 m 6 cm","mis":"M2-2-u3-X03"},{"t":"7 m 1 cm","mis":"M2-2-u3-X11"},{"t":"16 m 7 cm","mis":"M2-2-u3-X02"}]},{"stem":"120 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["120 cm는 100 cm와 20 cm예요.","100 cm는 1 m예요.","그래서 120 cm = 1 m 20 cm예요."],"options":[{"t":"1 m 20 cm","correct":true},{"t":"12 m","mis":"M2-2-u3-X03"},{"t":"1 m 2 cm","mis":"M2-2-u3-X11"},{"t":"20 m 1 cm","mis":"M2-2-u3-X02"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#9','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C3',2,'mc','auto','칠판의 긴 쪽의 길이는 약 3 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],true,'{"seq":9,"concept":"M2-2-u3-C3","difficulty":2,"kind":"mc","stem":"칠판의 긴 쪽의 길이는 약 3 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["칠판은 양팔을 세 번쯤 벌린 만큼 길어요.","약 3 cm는 손가락 한 마디쯤이라 너무 짧아요.","그래서 칠판의 긴 쪽은 약 3 m예요."],"variant_rule":{"alt":[{"stem":"필통의 길이는 약 15 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["필통은 손에 쥘 만큼 짧아요.","약 15 m는 교실 두 칸보다 길어요.","그래서 필통의 길이는 약 15 cm예요."]},{"stem":"교실 문의 높이는 약 200 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["교실 문은 어른 키보다 조금 높아요.","약 200 m는 운동장보다 훨씬 길어요.","그래서 약 200 cm — 약 2 m라고도 해요."]},{"stem":"교실의 짧은 쪽의 길이는 약 7 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["교실은 여러 사람이 지낼 만큼 넓어요.","약 7 cm는 지우개 두 개쯤이라 너무 짧아요.","그래서 교실의 짧은 쪽은 약 7 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_basic#10','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',3,'ox','auto','716 cm는 71 m 6 cm와 같은 길이예요.',ARRAY['M2-2-u3-X03']::text[],true,'{"seq":10,"concept":"M2-2-u3-C2","difficulty":3,"kind":"ox","stem":"716 cm는 71 m 6 cm와 같은 길이예요.","answer":"X","reason_options":[{"t":"716 cm는 700 cm와 16 cm라서 7 m 16 cm니까","correct":true},{"t":"앞의 두 숫자를 m로 읽으면 되니까","mis":"M2-2-u3-X03"}],"mis":"M2-2-u3-X03","explanation":["716 cm = 700 cm + 16 cm예요.","700 cm는 7 m예요.","그래서 716 cm = 7 m 16 cm — 7 m보다 조금 더 긴 길이예요."],"variant_rule":{"alt":[{"stem":"573 cm는 5 m 73 cm와 같은 길이예요.","answer":"O","reason_options":[{"t":"573 cm는 500 cm와 73 cm라서 5 m 73 cm니까","correct":true},{"t":"앞의 두 숫자를 m로 읽어 57 m 3 cm니까","mis":"M2-2-u3-X03"}],"explanation":["573 cm = 500 cm + 73 cm예요.","500 cm는 5 m예요.","그래서 573 cm = 5 m 73 cm로 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#1','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C1',2,'match','auto','단원 첫 그림에서 마을 사람들이 한 말과 이 단원에서 배울 것을 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":2,"kind":"match","stem":"단원 첫 그림에서 마을 사람들이 한 말과 이 단원에서 배울 것을 이으세요.","pairs":[{"l":"미술관 — 「cm보다 더 큰 단위는 없을까?」","r":"1 m 알기"},{"l":"나무 공방 — 「필요한 나무의 길이를 구해 볼까?」","r":"길이의 합"},{"l":"나무 공방 — 「사용하고 남은 부분의 길이는 얼마일까?」","r":"길이의 차"}],"mis":"M2-2-u3-X10","explanation":["cm보다 큰 단위를 찾는 것은 1 m를 배우는 일이에요.","두 나무의 길이를 모으면 합, 쓰고 남은 길이는 차예요.","길이 재기는 여러 직업에서 쓰여요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 단원 첫 그림에서 마을 사람들이 한 말과 이 단원에서 배울 것을 이으세요.","pairs":[{"l":"동물 연구소 — 「악어의 몸길이를 어림해 볼까?」","r":"1 m를 기준으로 어림하기"},{"l":"축구장 — 「내 걸음으로 축구 골대 긴 쪽의 길이를 어림해 볼까?」","r":"몸의 부분으로 어림하기"},{"l":"미술관 — 「cm보다 더 큰 단위는 없을까?」","r":"1 m 알기"}],"explanation":["악어의 몸길이는 1 m가 몇 번쯤인지로 어림해요.","걸음은 몸의 부분이라 걸음으로 어림할 수 있어요.","cm보다 큰 단위는 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#2','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',2,'match','auto','같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C2","difficulty":2,"kind":"match","stem":"같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.","pairs":[{"l":"120 cm","r":"1 m 20 cm"},{"l":"573 cm","r":"5 m 73 cm"},{"l":"405 cm","r":"4 m 5 cm"}],"mis":"M2-2-u3-X03","explanation":["120 cm = 100 cm + 20 cm = 1 m 20 cm예요.","573 cm = 500 cm + 73 cm = 5 m 73 cm예요.","405 cm = 400 cm + 5 cm = 4 m 5 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.","pairs":[{"l":"716 cm","r":"7 m 16 cm"},{"l":"200 cm","r":"2 m"},{"l":"300 cm","r":"3 m"}],"explanation":["716 cm = 700 cm + 16 cm = 7 m 16 cm예요.","200 cm는 100 cm가 2번 — 2 m예요.","300 cm는 100 cm가 3번 — 3 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#3','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C1',3,'mc','auto','1 m를 10 cm 자로 재면 몇 번 재어야 하나요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":3,"concept":"M2-2-u3-C1","difficulty":3,"kind":"mc","stem":"1 m를 10 cm 자로 재면 몇 번 재어야 하나요?","options":[{"t":"10번","correct":true},{"t":"100번","mis":"M2-2-u3-X01"},{"t":"1번","mis":"M2-2-u3-X01"}],"explanation":["10 cm 자로 한 번 재면 10 cm예요.","10 cm가 10번이면 100 cm예요.","100 cm는 1 m — 그래서 10번이에요."],"variant_rule":{"alt":[{"stem":"1 m는 1 cm를 몇 번 이은 길이인가요?","options":[{"t":"100번","correct":true},{"t":"10번","mis":"M2-2-u3-X01"},{"t":"1000번","mis":"M2-2-u3-X01"}],"explanation":["1 cm가 10번이면 10 cm예요.","1 cm가 100번이면 100 cm예요.","100 cm는 1 m — 그래서 100번이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#4','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'error','auto','405 cm를 몇 m 몇 cm로 나타냈어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],true,'{"seq":4,"concept":"M2-2-u3-C2","difficulty":3,"kind":"error","stem":"405 cm를 몇 m 몇 cm로 나타냈어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「405 cm는 4 m 50 cm야.」","correct":true,"mis_target":"M2-2-u3-X09"},{"t":"수찬 — 「400 cm와 5 cm로 갈라서 4 m 5 cm야.」","mis":"M2-2-u3-X16"},{"t":"슬기 — 「4 m 5 cm는 4 미터 5 센티미터라고 읽어.」","mis":"M2-2-u3-X16"}],"explanation":["405 cm = 400 cm + 5 cm예요.","400 cm는 4 m라서 4 m 5 cm예요.","지아는 5 cm를 50 cm처럼 보았어요 — 4 m 50 cm는 450 cm예요."],"variant_rule":{"alt":[{"stem":"5 m 73 cm를 몇 cm로 나타냈어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연우 — 「5와 73을 더해서 78 cm야.」","correct":true,"mis_target":"M2-2-u3-X04"},{"t":"세미 — 「500 cm와 73 cm를 모아서 573 cm야.」","mis":"M2-2-u3-X16"},{"t":"지아 — 「5 m는 500 cm라서 573 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["5 m는 500 cm예요.","500 cm와 73 cm를 모으면 573 cm예요.","연우는 m의 수와 cm의 수를 그냥 더했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#5','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','716 cm를 7 m 16 cm로 나타내면 좋은 점은 무엇인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X05']::text[],false,'{"seq":5,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"716 cm를 7 m 16 cm로 나타내면 좋은 점은 무엇인가요?","options":[{"t":"7 m보다 조금 더 긴 길이라는 것을 쉽게 알 수 있어요","correct":true},{"t":"7 m 16 cm는 716 cm보다 더 긴 길이가 돼요","mis":"M2-2-u3-X01"},{"t":"길이는 cm로만 나타내야 바르게 쓴 것이에요","mis":"M2-2-u3-X05"}],"explanation":["716 cm와 7 m 16 cm는 같은 길이예요.","7 m 16 cm라고 쓰면 「7 m와 16 cm」가 한눈에 보여요.","그래서 길이가 어느 정도인지 쉽게 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#6','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#7','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C3',3,'mc','auto','교실 문의 높이는 약 200 cm예요. 이 길이를 m로 나타내면 어느 것인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":7,"concept":"M2-2-u3-C3","difficulty":3,"kind":"mc","stem":"교실 문의 높이는 약 200 cm예요. 이 길이를 m로 나타내면 어느 것인가요?","options":[{"t":"약 2 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X01"},{"t":"약 200 m","mis":"M2-2-u3-X01"}],"explanation":["100 cm는 1 m예요.","200 cm는 100 cm가 2번 — 2 m예요.","그래서 교실 문의 높이는 약 2 m예요."],"variant_rule":{"alt":[{"stem":"칠판의 긴 쪽의 길이는 약 3 m예요. 이 길이를 cm로 나타내면 어느 것인가요?","options":[{"t":"약 300 cm","correct":true},{"t":"약 30 cm","mis":"M2-2-u3-X01"},{"t":"약 3 cm","mis":"M2-2-u3-X01"}],"explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번 — 300 cm예요.","그래서 칠판의 긴 쪽은 약 300 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#8','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',4,'essay','teacher','405 cm를 「몇 m 몇 cm」로 나타내는 방법을 세 단계로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C2","difficulty":4,"kind":"essay","stem":"405 cm를 「몇 m 몇 cm」로 나타내는 방법을 세 단계로 설명해 보세요.","answer_guide":{"answer":"예: 첫째, 405 cm를 400 cm와 5 cm로 가른다. 둘째, 400 cm는 4 m이다. 셋째, 405 cm = 4 m 5 cm로 나타낸다.","scoring_points":["405 cm를 400 cm와 5 cm로 갈랐는가","400 cm가 4 m임을 썼는가","4 m 5 cm라고 바르게 나타냈는가(4 m 50 cm 아님)"]},"explanation":["먼저 몇백 cm와 몇 cm로 갈라요.","몇백 cm를 몇 m로 바꾸어요.","그래서 405 cm = 4 m 5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#9','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C3',4,'essay','teacher','미술관 그림의 긴 쪽은 600 cm예요. 이 길이를 cm로만 나타내면 어떤 점이 불편한지 쓰고, 더 편리하게 나타내 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C3","difficulty":4,"kind":"essay","stem":"미술관 그림의 긴 쪽은 600 cm예요. 이 길이를 cm로만 나타내면 어떤 점이 불편한지 쓰고, 더 편리하게 나타내 보세요.","answer_guide":{"answer":"예: 600 cm는 1 cm로 600번이라 수가 너무 크고 바닥에 재기도 번거롭다. 100 cm가 1 m이므로 600 cm는 6 m로 나타내면 편리하다.","scoring_points":["1 cm로 600번이라 수가 크다(번거롭다)고 썼는가","100 cm = 1 m를 썼는가","6 m로 바르게 나타냈는가"]},"explanation":["600 cm는 1 cm가 600번이에요.","100 cm가 1 m이니 600 cm는 6 m예요.","긴 길이는 m로 나타내면 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L02_challenge#10','math',2,2,'u3','L02','tb_g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',4,'mc','auto','길이가 다른 하나는 어느 것인가요?',ARRAY['M2-2-u3-X11']::text[],false,'{"seq":10,"concept":"M2-2-u3-C2","difficulty":4,"kind":"mc","stem":"길이가 다른 하나는 어느 것인가요?","options":[{"t":"1 m 2 cm","correct":true},{"t":"120 cm","mis":"M2-2-u3-X11"},{"t":"1 m 20 cm","mis":"M2-2-u3-X11"},{"t":"100 cm와 20 cm를 모은 길이","mis":"M2-2-u3-X11"}],"explanation":["120 cm = 100 cm + 20 cm = 1 m 20 cm예요.","1 m 2 cm는 100 cm와 2 cm라서 102 cm예요.","그래서 길이가 다른 하나는 1 m 2 cm예요 — 20의 0을 떼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#1','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','수찬이의 일기에 「직업에 따라 서로 다른 자를 사용한다」고 썼어요. 공이나 나무의 둘레처럼 둥근 부분이 있는 물건의 길이를 잴 때 알맞은 자는 어느 것인가요?',ARRAY['M2-2-u3-X19']::text[],true,'{"seq":1,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"수찬이의 일기에 「직업에 따라 서로 다른 자를 사용한다」고 썼어요. 공이나 나무의 둘레처럼 둥근 부분이 있는 물건의 길이를 잴 때 알맞은 자는 어느 것인가요?","options":[{"t":"줄자","correct":true},{"t":"곧은자","mis":"M2-2-u3-X19"},{"t":"15 cm 곧은자","mis":"M2-2-u3-X19"}],"explanation":["줄자는 부드럽게 휘어요.","그래서 공이나 나무의 둘레에 감아 잴 수 있어요.","곧은자는 휘지 않아 둥근 부분을 재기 어려워요."],"variant_rule":{"alt":[{"stem":"짧고 곧은 연필의 길이를 잴 때 쓰기 편한 자는 어느 것인가요?","options":[{"t":"곧은자","correct":true},{"t":"10 m 줄자로만 재야 해요","mis":"M2-2-u3-X19"},{"t":"자 없이 걸음으로 재요","mis":"M2-2-u3-X13"}],"explanation":["곧은자는 짧고 곧은 물건의 길이를 잴 때 편해요.","연필은 짧고 곧아요.","줄자는 1 m보다 긴 물건이나 둥근 부분을 잴 때 편해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#2','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','줄자로 책상의 길이를 재요. 책상의 한끝을 줄자의 어느 눈금에 맞추어야 하나요?',ARRAY['M2-2-u3-X06']::text[],false,'{"seq":2,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"줄자로 책상의 길이를 재요. 책상의 한끝을 줄자의 어느 눈금에 맞추어야 하나요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M2-2-u3-X06"},{"t":"140","mis":"M2-2-u3-X06"}],"explanation":["한끝을 눈금 0에 맞춰야 해요.","그래야 다른 끝의 눈금이 바로 길이가 돼요.","눈금 1에 맞추면 1 cm만큼 길게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#3','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'sa','auto','책상의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"책상의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 140이니 140 cm예요.","140 cm는 1 m 40 cm라고도 나타내요."],"answer":["140"],"asset":{"type":"tape","len":140,"label":"책상"},"variant_rule":{"alt":[{"stem":"소파의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["소파의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 250이니 250 cm예요.","250 cm는 2 m 50 cm라고도 나타내요."],"answer":["250"],"asset":{"type":"tape","len":250,"label":"소파"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#4','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','알림판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"알림판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["알림판의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 120이니 120 cm예요.","120 cm = 100 cm + 20 cm = 1 m 20 cm예요."],"options":[{"t":"1 m 20 cm","correct":true},{"t":"12 m","mis":"M2-2-u3-X03"},{"t":"1 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":120,"label":"알림판"},"variant_rule":{"alt":[{"stem":"선생님 책상의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["선생님 책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 180이니 180 cm예요.","180 cm = 100 cm + 80 cm = 1 m 80 cm예요."],"options":[{"t":"1 m 80 cm","correct":true},{"t":"18 m","mis":"M2-2-u3-X03"},{"t":"1 m 81 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":180,"label":"선생님 책상"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#5','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":5,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["사물함의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."],"options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함"},"variant_rule":{"alt":[{"stem":"소파의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["소파의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 250이니 250 cm예요.","250 cm = 200 cm + 50 cm = 2 m 50 cm예요."],"options":[{"t":"2 m 50 cm","correct":true},{"t":"25 m","mis":"M2-2-u3-X03"},{"t":"2 m 51 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":250,"label":"소파"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#6','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'match','auto','멀리 던지기 기록표에서 슬기의 기록을 몇 cm로 나타낸 것과 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u3-C4","difficulty":2,"kind":"match","stem":"멀리 던지기 기록표에서 슬기의 기록을 몇 cm로 나타낸 것과 이으세요.","pairs":[{"l":"제기 2 m 10 cm","r":"210 cm"},{"l":"배드민턴공 3 m 50 cm","r":"350 cm"},{"l":"종이컵 3 m 30 cm","r":"330 cm"}],"mis":"M2-2-u3-X02","explanation":["2 m 10 cm = 200 cm + 10 cm = 210 cm예요.","3 m 50 cm = 300 cm + 50 cm = 350 cm예요.","3 m 30 cm = 300 cm + 30 cm = 330 cm예요."],"variant_rule":{"alt":[{"stem":"멀리 던지기 기록표에서 지아의 기록을 몇 cm로 나타낸 것과 이으세요.","pairs":[{"l":"제기 1 m 90 cm","r":"190 cm"},{"l":"배드민턴공 4 m 30 cm","r":"430 cm"},{"l":"종이컵 2 m 80 cm","r":"280 cm"}],"explanation":["1 m 90 cm = 100 cm + 90 cm = 190 cm예요.","4 m 30 cm = 400 cm + 30 cm = 430 cm예요.","2 m 80 cm = 200 cm + 80 cm = 280 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#7','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','멀리 던지기 제기 던지기 기록이에요. 슬기 2 m 10 cm, 지아 1 m 90 cm, 수찬 1 m 60 cm, 연우 2 m 20 cm. 제기를 가장 멀리 던진 사람은 누구인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"멀리 던지기 제기 던지기 기록이에요. 슬기 2 m 10 cm, 지아 1 m 90 cm, 수찬 1 m 60 cm, 연우 2 m 20 cm. 제기를 가장 멀리 던진 사람은 누구인가요?","options":[{"t":"연우","correct":true},{"t":"지아","mis":"M2-2-u3-X18"},{"t":"슬기","mis":"M2-2-u3-X08"}],"explanation":["먼저 m의 수를 견주면 슬기와 연우가 2 m예요.","2 m끼리는 cm를 견주어 20 cm가 10 cm보다 길어요.","그래서 연우가 가장 멀리 던졌어요 — cm의 수 90만 보면 안 돼요."],"variant_rule":{"alt":[{"stem":"멀리 던지기 배드민턴공 던지기 기록이에요. 슬기 3 m 50 cm, 지아 4 m 30 cm, 수찬 5 m 10 cm, 연우 4 m 20 cm. 배드민턴공을 가장 멀리 던진 사람은 누구인가요?","options":[{"t":"수찬","correct":true},{"t":"슬기","mis":"M2-2-u3-X18"},{"t":"지아","mis":"M2-2-u3-X08"}],"explanation":["먼저 m의 수를 견주어요.","5 m인 수찬이가 가장 멀어요.","cm의 수 50만 보고 슬기를 고르면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#8','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'ox','auto','멀리 던지기에서는 출발선에서 물체가 바닥에 떨어진 곳까지 곧게 재요.',ARRAY['M2-2-u3-X20']::text[],true,'{"seq":8,"concept":"M2-2-u3-C4","difficulty":2,"kind":"ox","stem":"멀리 던지기에서는 출발선에서 물체가 바닥에 떨어진 곳까지 곧게 재요.","answer":"O","reason_options":[{"t":"거리는 직선거리로 재야 하니까","correct":true},{"t":"물체가 굴러간 길을 따라 구불구불 재도 되니까","mis":"M2-2-u3-X20"}],"mis":"M2-2-u3-X20","explanation":["멀리 던지기는 출발선에서 떨어진 곳까지의 거리를 재요.","거리를 잴 때는 반드시 곧게(직선거리로) 재요.","그래서 바른 말이에요."],"variant_rule":{"alt":[{"stem":"줄자는 느슨하게 늘어뜨린 채로 재도 길이가 똑같이 나와요.","answer":"X","reason_options":[{"t":"줄자가 처지면 실제보다 길게 읽으니 팽팽하게 펴서 재야 하니까","correct":true},{"t":"줄자는 어떻게 대도 눈금이 같으니까","mis":"M2-2-u3-X20"}],"explanation":["줄자가 처지면 굽은 만큼 눈금이 더 나가요.","그래서 줄자는 팽팽하게 펴서 재요.","틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#9','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','줄자로 책상을 재었더니 끝의 눈금이 140이었어요. 책상의 길이를 두 가지 방법으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X01']::text[],true,'{"seq":9,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"줄자로 책상을 재었더니 끝의 눈금이 140이었어요. 책상의 길이를 두 가지 방법으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"140 cm, 1 m 40 cm","correct":true},{"t":"140 cm, 14 m","mis":"M2-2-u3-X03"},{"t":"140 m, 1 m 40 cm","mis":"M2-2-u3-X01"}],"explanation":["끝의 눈금이 140이니 140 cm예요.","140 cm = 100 cm + 40 cm = 1 m 40 cm예요.","그래서 140 cm 또는 1 m 40 cm로 나타내요."],"variant_rule":{"alt":[{"stem":"줄자로 사물함을 재었더니 끝의 눈금이 520이었어요. 사물함의 길이를 두 가지 방법으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"520 cm, 5 m 20 cm","correct":true},{"t":"520 cm, 52 m","mis":"M2-2-u3-X03"},{"t":"520 cm, 5 m 2 cm","mis":"M2-2-u3-X11"}],"explanation":["끝의 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요.","그래서 520 cm 또는 5 m 20 cm로 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_basic#10','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',3,'mc','auto','색종이를 10 cm씩 잘라 만든 종이띠를 겹치지 않게 이어 붙여 1 m 자를 만들려고 해요. 종이띠는 몇 개 있어야 하나요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"색종이를 10 cm씩 잘라 만든 종이띠를 겹치지 않게 이어 붙여 1 m 자를 만들려고 해요. 종이띠는 몇 개 있어야 하나요?","options":[{"t":"10개","correct":true},{"t":"100개","mis":"M2-2-u3-X01"},{"t":"1개","mis":"M2-2-u3-X01"}],"explanation":["종이띠 하나는 10 cm예요.","10 cm가 10번이면 100 cm예요.","100 cm는 1 m라서 종이띠 10개가 있어야 해요."],"variant_rule":{"alt":[{"stem":"종이띠 10개로 만든 1 m 자로 칠판을 재었더니 1 m 자를 두 번 대고 40 cm가 남았어요. 칠판의 길이는 얼마인가요?","options":[{"t":"2 m 40 cm","correct":true},{"t":"240 m","mis":"M2-2-u3-X01"},{"t":"2 m 4 cm","mis":"M2-2-u3-X11"}],"explanation":["1 m 자를 두 번 대면 2 m예요.","40 cm가 더 있으니 2 m 40 cm예요.","240 cm라고도 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#1','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',2,'sa','auto','선생님 책상의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"선생님 책상의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["선생님 책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 180이니 180 cm예요.","180 cm는 1 m 80 cm라고도 나타내요."],"answer":["180"],"asset":{"type":"tape","len":180,"label":"선생님 책상"},"variant_rule":{"alt":[{"stem":"알림판의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["알림판의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 120이니 120 cm예요.","120 cm는 1 m 20 cm라고도 나타내요."],"answer":["120"],"asset":{"type":"tape","len":120,"label":"알림판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#2','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',2,'mc','auto','줄자로 재기에 알맞은 것끼리 모은 것은 어느 것인가요?',ARRAY['M2-2-u3-X19']::text[],false,'{"seq":2,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"줄자로 재기에 알맞은 것끼리 모은 것은 어느 것인가요?","options":[{"t":"사물함의 긴 쪽, 나무의 둘레","correct":true},{"t":"연필, 지우개","mis":"M2-2-u3-X19"},{"t":"공책의 짧은 쪽, 필통","mis":"M2-2-u3-X19"}],"explanation":["줄자는 1 m보다 긴 물건이나 둥근 부분을 잴 때 편해요.","사물함의 긴 쪽은 1 m보다 길고, 나무의 둘레는 둥글어요.","연필·지우개·공책·필통은 곧은자로 재면 편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#3','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','책상의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 책상의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"책상의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 책상의 길이는 몇 cm인가요?","explanation":["책상의 한끝은 눈금 2, 다른 끝은 눈금 142에 있어요.","142 − 2 = 140이니 140 cm예요.","끝 눈금 142를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"options":[{"t":"140 cm","correct":true},{"t":"142 cm","mis":"M2-2-u3-X06"},{"t":"141 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":140,"label":"책상","s":2},"variant_rule":{"alt":[{"stem":"알림판의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 알림판의 길이는 몇 cm인가요?","explanation":["알림판의 한끝은 눈금 3, 다른 끝은 눈금 123에 있어요.","123 − 3 = 120이니 120 cm예요.","끝 눈금 123을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"options":[{"t":"120 cm","correct":true},{"t":"123 cm","mis":"M2-2-u3-X06"},{"t":"121 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":120,"label":"알림판","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#4','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','제기 던지기 기록을 짧은 것부터 늘어놓았어요. 바르게 늘어놓은 것은 어느 것인가요? (슬기 2 m 10 cm · 지아 1 m 90 cm · 수찬 1 m 60 cm · 연우 2 m 20 cm)',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"제기 던지기 기록을 짧은 것부터 늘어놓았어요. 바르게 늘어놓은 것은 어느 것인가요? (슬기 2 m 10 cm · 지아 1 m 90 cm · 수찬 1 m 60 cm · 연우 2 m 20 cm)","options":[{"t":"수찬, 지아, 슬기, 연우","correct":true},{"t":"슬기, 연우, 수찬, 지아","mis":"M2-2-u3-X18"},{"t":"연우, 슬기, 지아, 수찬","mis":"M2-2-u3-X16"}],"explanation":["m의 수가 1인 수찬과 지아가 2 m인 슬기와 연우보다 짧아요.","1 m끼리는 60 cm < 90 cm, 2 m끼리는 10 cm < 20 cm예요.","그래서 수찬, 지아, 슬기, 연우 — cm의 수만 견주면 안 돼요."],"variant_rule":{"alt":[{"stem":"종이컵 던지기 기록을 짧은 것부터 늘어놓았어요. 바르게 늘어놓은 것은 어느 것인가요? (슬기 3 m 30 cm · 지아 2 m 80 cm · 수찬 4 m 20 cm · 연우 3 m 10 cm)","options":[{"t":"지아, 연우, 슬기, 수찬","correct":true},{"t":"연우, 수찬, 슬기, 지아","mis":"M2-2-u3-X18"},{"t":"수찬, 슬기, 연우, 지아","mis":"M2-2-u3-X16"}],"explanation":["m의 수부터 견주면 지아 2 m가 가장 짧고 수찬 4 m가 가장 길어요.","3 m인 슬기와 연우는 cm로 견주어 10 cm < 30 cm예요.","그래서 지아, 연우, 슬기, 수찬이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#5','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'error','auto','책상의 끝의 눈금이 140이었어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X16']::text[],true,'{"seq":5,"concept":"M2-2-u3-C4","difficulty":3,"kind":"error","stem":"책상의 끝의 눈금이 140이었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「끝의 눈금이 140이니까 14 m야.」","correct":true,"mis_target":"M2-2-u3-X03"},{"t":"수찬 — 「한끝을 눈금 0에 맞추고 다른 끝의 눈금을 읽었어.」","mis":"M2-2-u3-X16"},{"t":"슬기 — 「140 cm는 1 m 40 cm라고도 해.」","mis":"M2-2-u3-X16"}],"explanation":["끝의 눈금 140은 140 cm예요.","140 cm = 100 cm + 40 cm = 1 m 40 cm예요.","지아는 자리를 잘못 갈라 14 m라고 했어요."],"variant_rule":{"alt":[{"stem":"사물함의 끝의 눈금이 520이었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세미 — 「520 cm는 5 m 2 cm야.」","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"연우 — 「520 cm는 500 cm와 20 cm야.」","mis":"M2-2-u3-X16"},{"t":"지아 — 「520 cm는 5 m 20 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["520 cm = 500 cm + 20 cm예요.","500 cm는 5 m라서 5 m 20 cm예요.","세미는 20의 0을 떼어 5 m 2 cm라고 했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#6','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','소파의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":6,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"소파의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["소파의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 250이니 250 cm예요.","250 cm = 200 cm + 50 cm = 2 m 50 cm예요."],"options":[{"t":"2 m 50 cm","correct":true},{"t":"25 m","mis":"M2-2-u3-X03"},{"t":"2 m 51 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":250,"label":"소파"},"variant_rule":{"alt":[{"stem":"책상의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 140이니 140 cm예요.","140 cm = 100 cm + 40 cm = 1 m 40 cm예요."],"options":[{"t":"1 m 40 cm","correct":true},{"t":"14 m","mis":"M2-2-u3-X03"},{"t":"1 m 41 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":140,"label":"책상"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#7','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','슬기가 던진 제기가 출발선에서 곧게 2 m 10 cm인 곳에 떨어진 뒤 옆으로 굴러갔어요. 기록으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X20']::text[],false,'{"seq":7,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"슬기가 던진 제기가 출발선에서 곧게 2 m 10 cm인 곳에 떨어진 뒤 옆으로 굴러갔어요. 기록으로 알맞은 것은 어느 것인가요?","options":[{"t":"떨어진 곳까지 곧게 잰 2 m 10 cm","correct":true},{"t":"굴러가서 멈춘 곳까지 잰 길이","mis":"M2-2-u3-X20"},{"t":"떨어진 곳까지 구불구불 걸어간 길을 따라 잰 길이","mis":"M2-2-u3-X20"}],"explanation":["멀리 던지기는 출발선에서 물체가 바닥에 떨어진 곳까지 재요.","거리는 반드시 직선거리로 재요.","그래서 기록은 2 m 10 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#8','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'essay','teacher','집에서 1 m보다 긴 소파를 줄자로 재었더니 끝의 눈금이 250이었어요. 줄자로 재는 방법과 소파의 길이를 두 가지 방법으로 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C4","difficulty":4,"kind":"essay","stem":"집에서 1 m보다 긴 소파를 줄자로 재었더니 끝의 눈금이 250이었어요. 줄자로 재는 방법과 소파의 길이를 두 가지 방법으로 써 보세요.","answer_guide":{"answer":"예: 소파의 한끝을 줄자의 눈금 0에 맞추고 줄자를 팽팽하게 펴서 다른 끝의 눈금을 읽는다. 소파의 길이는 250 cm, 또는 2 m 50 cm이다.","scoring_points":["한끝을 눈금 0에 맞춘다고 썼는가","다른 끝의 눈금을 읽는다고 썼는가","250 cm와 2 m 50 cm를 모두 썼는가"]},"explanation":["한끝을 눈금 0에 맞추어요.","다른 끝의 눈금 250을 읽으면 250 cm예요.","250 cm = 2 m 50 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#9','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'mc','auto','알림판의 한끝을 줄자의 눈금 3에 맞추었더니 다른 끝이 눈금 123에 닿았어요. 알림판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X03']::text[],false,'{"seq":9,"concept":"M2-2-u3-C4","difficulty":4,"kind":"mc","stem":"알림판의 한끝을 줄자의 눈금 3에 맞추었더니 다른 끝이 눈금 123에 닿았어요. 알림판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","options":[{"t":"1 m 20 cm","correct":true},{"t":"1 m 23 cm","mis":"M2-2-u3-X06"},{"t":"12 m 3 cm","mis":"M2-2-u3-X03"}],"explanation":["한끝이 0이 아니라 3에 있어요.","123 − 3 = 120이니 120 cm예요.","120 cm = 1 m 20 cm — 끝 눈금 123을 그대로 읽으면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L03_challenge#10','math',2,2,'u3','L03','tb_g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'essay','teacher','곧은자와 줄자의 같은 점과 다른 점을 쓰고, 각각 어떤 물건의 길이를 잴 때 편리한지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":4,"kind":"essay","stem":"곧은자와 줄자의 같은 점과 다른 점을 쓰고, 각각 어떤 물건의 길이를 잴 때 편리한지 써 보세요.","answer_guide":{"answer":"예: 둘 다 눈금이 있고 한끝을 0에 맞추어 길이를 잰다. 곧은자는 짧고 곧아서 연필처럼 짧고 곧은 물건을, 줄자는 길고 휘어져서 사물함처럼 1 m보다 긴 물건이나 나무의 둘레처럼 둥근 부분을 재기 편하다.","scoring_points":["같은 점(눈금·0에 맞춤)을 썼는가","다른 점(길이·휘어짐)을 썼는가","각 자로 재기 알맞은 물건을 바르게 들었는가"]},"explanation":["두 자 모두 눈금이 있고 0에 맞추어 재요.","곧은자는 짧고 곧은 물건, 줄자는 긴 물건과 둥근 부분에 알맞아요.","직업에 따라서도 서로 다른 자를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#1','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'mc','auto','1 m 70 cm인 나무와 1 m 20 cm인 나무를 겹치지 않게 이었어요. 이은 나무의 길이는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],false,'{"seq":1,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"1 m 70 cm인 나무와 1 m 20 cm인 나무를 겹치지 않게 이었어요. 이은 나무의 길이는 얼마인가요?","explanation":["m는 m끼리 더해요 — 1 + 1 = 2.","cm는 cm끼리 더해요 — 70 + 20 = 90.","그래서 1 m 70 cm + 1 m 20 cm = 2 m 90 cm예요."],"options":[{"t":"2 m 90 cm","correct":true},{"t":"2 m 9 cm","mis":"M2-2-u3-X11"},{"t":"3 m 90 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#2','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'mc','auto','나무 공방에서 1 m 70 cm인 나무판과 1 m 20 cm인 나무판으로 표지판을 만들어요. 줄자로 재지 않고 두 길이의 합을 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X04','M2-2-u3-X10']::text[],false,'{"seq":2,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"나무 공방에서 1 m 70 cm인 나무판과 1 m 20 cm인 나무판으로 표지판을 만들어요. 줄자로 재지 않고 두 길이의 합을 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"m는 m끼리, cm는 cm끼리 더해요","correct":true},{"t":"m의 수와 cm의 수를 모두 한꺼번에 더해요","mis":"M2-2-u3-X04"},{"t":"긴 길이에서 짧은 길이를 빼요","mis":"M2-2-u3-X10"}],"explanation":["길이는 같은 단위끼리 더해요.","m끼리 1 + 1 = 2, cm끼리 70 + 20 = 90이에요.","그래서 2 m 90 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#3','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C5","difficulty":1,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 1 + 1 = 2.","cm는 cm끼리 더해요 — 70 + 20 = 90.","그래서 1 m 70 cm + 1 m 20 cm = 2 m 90 cm예요."],"answer":["90"],"asset":{"type":"mcm_calc","a":[1,70],"b":[1,20],"op":"+","ask":"cm"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 40 + 50 = 90.","그래서 3 m 40 cm + 5 m 50 cm = 8 m 90 cm예요."],"answer":["90"],"asset":{"type":"mcm_calc","a":[3,40],"b":[5,50],"op":"+","ask":"cm"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#4','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'mc','auto','3 m 40 cm + 5 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 40 cm + 5 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 40 + 50 = 90.","그래서 3 m 40 cm + 5 m 50 cm = 8 m 90 cm예요."],"options":[{"t":"8 m 90 cm","correct":true},{"t":"2 m 10 cm","mis":"M2-2-u3-X10"},{"t":"8 m 9 cm","mis":"M2-2-u3-X11"}],"variant_rule":{"alt":[{"stem":"4 m 26 cm + 1 m 60 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 4 + 1 = 5.","cm는 cm끼리 더해요 — 26 + 60 = 86.","그래서 4 m 26 cm + 1 m 60 cm = 5 m 86 cm예요."],"options":[{"t":"5 m 86 cm","correct":true},{"t":"3 m 34 cm","mis":"M2-2-u3-X10"},{"t":"6 m 86 cm","mis":"M2-2-u3-X08"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#5','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','2 m 24 cm + 7 m 5 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"2 m 24 cm + 7 m 5 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 2 + 7 = 9.","cm는 cm끼리 더해요 — 24 + 5 = 29.","그래서 2 m 24 cm + 7 m 5 cm = 9 m 29 cm예요."],"options":[{"t":"9 m 29 cm","correct":true},{"t":"5 m 19 cm","mis":"M2-2-u3-X10"},{"t":"9 m 74 cm","mis":"M2-2-u3-X09"},{"t":"10 m 29 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#6','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','1 m 70 cm + 1 m 20 cm를 간단한 수 17 + 12로 바꾸어 생각했어요. 17 + 12 = 29에서 2와 9는 각각 무엇을 나타내나요?',ARRAY['M2-2-u3-X02','M2-2-u3-X09']::text[],false,'{"seq":6,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"1 m 70 cm + 1 m 20 cm를 간단한 수 17 + 12로 바꾸어 생각했어요. 17 + 12 = 29에서 2와 9는 각각 무엇을 나타내나요?","options":[{"t":"2는 2 m, 9는 90 cm","correct":true},{"t":"2는 2 cm, 9는 9 m","mis":"M2-2-u3-X02"},{"t":"2는 20 cm, 9는 9 cm","mis":"M2-2-u3-X09"}],"explanation":["1 m 70 cm를 17로, 1 m 20 cm를 12로 생각했어요.","앞자리는 m의 수, 뒷자리는 cm의 몇십이에요.","그래서 29는 2 m 90 cm — 자연수의 덧셈과 길이의 덧셈은 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#7','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','색 테이프 1 m 70 cm와 1 m 20 cm를 이어 붙여 줄자로 재었더니 2 m 90 cm였어요. 줄자로 재지 않고 같은 답을 얻는 식은 어느 것인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X04']::text[],false,'{"seq":7,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"색 테이프 1 m 70 cm와 1 m 20 cm를 이어 붙여 줄자로 재었더니 2 m 90 cm였어요. 줄자로 재지 않고 같은 답을 얻는 식은 어느 것인가요?","options":[{"t":"1 m 70 cm + 1 m 20 cm","correct":true},{"t":"1 m 70 cm − 1 m 20 cm","mis":"M2-2-u3-X10"},{"t":"1 + 70 + 1 + 20 = 92 (cm)","mis":"M2-2-u3-X04"}],"explanation":["이어 붙인 길이는 두 길이의 합이에요.","1 m 70 cm + 1 m 20 cm = 2 m 90 cm예요.","m의 수와 cm의 수를 섞어 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#8','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":8,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 7 = 12.","cm는 cm끼리 더해요 — 35 + 40 = 75.","그래서 5 m 35 cm + 7 m 40 cm = 12 m 75 cm예요."],"options":[{"t":"12 m 75 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"13 m 75 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#9','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'error','auto','1 m 30 cm와 1 m 50 cm의 합을 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X16']::text[],false,'{"seq":9,"concept":"M2-2-u3-C5","difficulty":2,"kind":"error","stem":"1 m 30 cm와 1 m 50 cm의 합을 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"세미 — 「2 m 8 cm야.」","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"수찬 — 「m끼리 2, cm끼리 80이니 2 m 80 cm야.」","mis":"M2-2-u3-X16"},{"t":"지아 — 「130 cm + 150 cm = 280 cm, 2 m 80 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["m끼리 1 + 1 = 2, cm끼리 30 + 50 = 80이에요.","130 cm + 150 cm = 280 cm로 구해도 2 m 80 cm예요.","세미는 80의 0을 떼어 2 m 8 cm라고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_basic#10','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',3,'mc','auto','11 m 35 cm + 7 m 23 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":10,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"11 m 35 cm + 7 m 23 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 11 + 7 = 18.","cm는 cm끼리 더해요 — 35 + 23 = 58.","그래서 11 m 35 cm + 7 m 23 cm = 18 m 58 cm예요."],"options":[{"t":"18 m 58 cm","correct":true},{"t":"4 m 12 cm","mis":"M2-2-u3-X10"},{"t":"19 m 58 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#1','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',2,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u3-C5","difficulty":2,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 2 + 7 = 9.","cm는 cm끼리 더해요 — 24 + 5 = 29.","그래서 2 m 24 cm + 7 m 5 cm = 9 m 29 cm예요."],"answer":["29"],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#2','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',2,'mc','auto','색 테이프 두 장을 겹치지 않게 이어 붙였어요. 이은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":2,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"색 테이프 두 장을 겹치지 않게 이어 붙였어요. 이은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 40 + 50 = 90.","그래서 3 m 40 cm + 5 m 50 cm = 8 m 90 cm예요."],"options":[{"t":"8 m 90 cm","correct":true},{"t":"2 m 10 cm","mis":"M2-2-u3-X10"},{"t":"8 m 9 cm","mis":"M2-2-u3-X11"}],"asset":{"type":"mbar","parts":[[3,40],[5,50]],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#3','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'error','auto','친구들이 길이의 합을 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],false,'{"seq":3,"concept":"M2-2-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 길이의 합을 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"지아 — 「2 m 24 cm + 7 m 5 cm = 9 m 74 cm」","correct":true,"mis_target":"M2-2-u3-X09"},{"t":"수찬 — 「4 m 26 cm + 1 m 60 cm = 5 m 86 cm」","mis":"M2-2-u3-X16"},{"t":"슬기 — 「3 m 40 cm + 5 m 50 cm = 8 m 90 cm」","mis":"M2-2-u3-X16"}],"explanation":["7 m 5 cm의 cm는 5예요.","cm끼리 24 + 5 = 29 — 2 m 24 cm + 7 m 5 cm = 9 m 29 cm예요.","지아는 5를 50처럼 더했어요."],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"both","said":[9,74]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#4','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','두 길이의 합이 9 m보다 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X08']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 길이의 합이 9 m보다 긴 것은 어느 것인가요?","options":[{"t":"2 m 24 cm + 7 m 5 cm","correct":true},{"t":"3 m 40 cm + 5 m 50 cm","mis":"M2-2-u3-X18"},{"t":"4 m 26 cm + 1 m 60 cm","mis":"M2-2-u3-X08"}],"explanation":["합을 구하면 9 m 29 cm, 8 m 90 cm, 5 m 86 cm예요.","m의 수부터 견주면 9 m 29 cm만 9 m보다 길어요.","8 m 90 cm는 cm의 수가 커도 9 m보다 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#5','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'sa','auto','4 m 26 cm + 1 m □ cm = 5 m 86 cm예요. □ 안에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":3,"kind":"sa","stem":"4 m 26 cm + 1 m □ cm = 5 m 86 cm예요. □ 안에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["m끼리 4 + 1 = 5로 맞아요.","cm끼리 26 + □ = 86이어야 해요.","26에 60을 더하면 86 — □는 60이에요."],"variant_rule":{"alt":[{"stem":"3 m □ cm + 5 m 50 cm = 8 m 90 cm예요. □ 안에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["m끼리 3 + 5 = 8로 맞아요.","cm끼리 □ + 50 = 90이어야 해요.","40에 50을 더하면 90 — □는 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#6','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 출발점에서 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러가 도착했어요. 출발점에서 도착점까지의 거리는 10 m보다 얼마나 더 먼가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":6,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 출발점에서 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러가 도착했어요. 출발점에서 도착점까지의 거리는 10 m보다 얼마나 더 먼가요?","options":[{"t":"2 m 75 cm","correct":true},{"t":"12 m 75 cm","mis":"M2-2-u3-X16"},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"}],"explanation":["굴러간 거리는 5 m 35 cm + 7 m 40 cm = 12 m 75 cm예요.","12 m 75 cm는 10 m와 2 m 75 cm예요.","그래서 10 m보다 2 m 75 cm 더 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#7','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'blank','auto','길이의 합을 구하는 순서예요. 첫째, 같은 단위끼리 맞추어 써요. 둘째, (        ) 더해요. 셋째, 두 길이의 합을 말해요.',ARRAY['M2-2-u3-X04','M2-2-u3-X10']::text[],false,'{"seq":7,"concept":"M2-2-u3-C5","difficulty":3,"kind":"blank","stem":"길이의 합을 구하는 순서예요. 첫째, 같은 단위끼리 맞추어 써요. 둘째, (        ) 더해요. 셋째, 두 길이의 합을 말해요.","options":[{"t":"cm는 cm끼리, m는 m끼리","correct":true},{"t":"m의 수와 cm의 수를 한꺼번에","mis":"M2-2-u3-X04"},{"t":"긴 길이에서 짧은 길이를","mis":"M2-2-u3-X10"}],"explanation":["같은 단위끼리 줄을 맞추어 써요.","cm는 cm끼리, m는 m끼리 더해요 — m부터 더해도 돼요.","마지막에 두 길이의 합을 「몇 m 몇 cm」로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#8','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'essay','teacher','모둠에서 1 m보다 긴 물건 두 개를 재었어요. 알림판은 1 m 20 cm, 선생님 책상은 1 m 80 cm예요. 두 길이의 합을 구하고, cm끼리 더한 값이 100이 될 때 어떻게 했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"모둠에서 1 m보다 긴 물건 두 개를 재었어요. 알림판은 1 m 20 cm, 선생님 책상은 1 m 80 cm예요. 두 길이의 합을 구하고, cm끼리 더한 값이 100이 될 때 어떻게 했는지 설명해 보세요.","answer_guide":{"answer":"예: m끼리 1 + 1 = 2, cm끼리 20 + 80 = 100이다. 100 cm는 1 m이므로 2 m와 1 m를 모아 두 길이의 합은 3 m이다.","scoring_points":["m끼리·cm끼리 더했는가","100 cm = 1 m를 이용했는가","3 m라고 구했는가"]},"explanation":["cm끼리 더하면 100 cm가 돼요.","100 cm는 1 m — m끼리 더한 2 m에 1 m를 더해요.","그래서 두 길이의 합은 3 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#9','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'essay','teacher','자연수의 덧셈 17 + 12 = 29와 길이의 덧셈 1 m 70 cm + 1 m 20 cm는 어떤 점이 닮았는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"자연수의 덧셈 17 + 12 = 29와 길이의 덧셈 1 m 70 cm + 1 m 20 cm는 어떤 점이 닮았는지 설명해 보세요.","answer_guide":{"answer":"예: 둘 다 같은 자리(같은 단위)끼리 더한다. 17 + 12에서 십의 자리끼리, 일의 자리끼리 더하듯이 1 m 70 cm + 1 m 20 cm에서는 m끼리 1 + 1 = 2, cm끼리 70 + 20 = 90을 더해 2 m 90 cm가 된다.","scoring_points":["같은 자리(단위)끼리 더한다는 점을 썼는가","m끼리·cm끼리 더한 값을 썼는가","2 m 90 cm를 바르게 구했는가"]},"explanation":["자연수는 같은 자리끼리 더해요.","길이는 같은 단위끼리 더해요.","그래서 1 m 70 cm + 1 m 20 cm = 2 m 90 cm예요."],"asset":{"type":"mcm_calc","a":[1,70],"b":[1,20],"op":"+","ask":"show"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L04_challenge#10','math',2,2,'u3','L04','tb_g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'mc','auto','4 m 26 cm, 1 m 60 cm, 2 m 24 cm, 3 m 40 cm 가운데 두 길이를 더해 5 m 86 cm를 만들었어요. 더한 두 길이는 어느 것인가요?',ARRAY['M2-2-u3-X08']::text[],false,'{"seq":10,"concept":"M2-2-u3-C5","difficulty":4,"kind":"mc","stem":"4 m 26 cm, 1 m 60 cm, 2 m 24 cm, 3 m 40 cm 가운데 두 길이를 더해 5 m 86 cm를 만들었어요. 더한 두 길이는 어느 것인가요?","options":[{"t":"4 m 26 cm와 1 m 60 cm","correct":true},{"t":"2 m 24 cm와 3 m 40 cm","mis":"M2-2-u3-X08"},{"t":"4 m 26 cm와 2 m 24 cm","mis":"M2-2-u3-X08"}],"explanation":["4 m 26 cm + 1 m 60 cm는 m끼리 5, cm끼리 86 — 5 m 86 cm예요.","2 m 24 cm + 3 m 40 cm = 5 m 64 cm, 4 m 26 cm + 2 m 24 cm = 6 m 50 cm예요.","그래서 4 m 26 cm와 1 m 60 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#1','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'mc','auto','2 m 50 cm인 색 테이프에서 1 m 40 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":1,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"2 m 50 cm인 색 테이프에서 1 m 40 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 2 − 1 = 1.","cm는 cm끼리 빼요 — 50 − 40 = 10.","그래서 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요."],"options":[{"t":"1 m 10 cm","correct":true},{"t":"3 m 90 cm","mis":"M2-2-u3-X10"},{"t":"1 m 1 cm","mis":"M2-2-u3-X11"}],"asset":{"type":"mbar","parts":[[2,50],[1,40]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#2','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'mc','auto','나무 공예 기술자가 2 m 50 cm인 나무에서 1 m 40 cm를 사용하려고 해요. 남은 나무의 길이를 구하는 식은 어느 것인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":2,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"나무 공예 기술자가 2 m 50 cm인 나무에서 1 m 40 cm를 사용하려고 해요. 남은 나무의 길이를 구하는 식은 어느 것인가요?","options":[{"t":"2 m 50 cm − 1 m 40 cm","correct":true},{"t":"2 m 50 cm + 1 m 40 cm","mis":"M2-2-u3-X10"},{"t":"2 m 50 cm − 40 cm","mis":"M2-2-u3-X08"}],"explanation":["남은 길이는 처음 길이에서 사용한 길이를 빼요.","2 m 50 cm − 1 m 40 cm예요.","1 m 40 cm를 통째로 빼야 해요 — 40 cm만 빼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#3','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'sa','auto','세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C6","difficulty":1,"kind":"sa","stem":"세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 2 − 1 = 1.","cm는 cm끼리 빼요 — 50 − 40 = 10.","그래서 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요."],"answer":["1"],"asset":{"type":"mcm_calc","a":[2,50],"b":[1,40],"op":"-","ask":"m"},"variant_rule":{"alt":[{"stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 2 − 1 = 1.","cm는 cm끼리 빼요 — 50 − 40 = 10.","그래서 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요."],"answer":["10"],"asset":{"type":"mcm_calc","a":[2,50],"b":[1,40],"op":"-","ask":"cm"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#4','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'mc','auto','6 m 80 cm − 4 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],true,'{"seq":4,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"6 m 80 cm − 4 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 80 − 50 = 30.","그래서 6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요."],"options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}],"variant_rule":{"alt":[{"stem":"7 m 74 cm − 5 m 32 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 7 − 5 = 2.","cm는 cm끼리 빼요 — 74 − 32 = 42.","그래서 7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요."],"options":[{"t":"2 m 42 cm","correct":true},{"t":"3 m 42 cm","mis":"M2-2-u3-X08"},{"t":"2 m 52 cm","mis":"M2-2-u3-X08"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#5','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','4 m 29 cm − 1 m 6 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"4 m 29 cm − 1 m 6 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 1 = 3.","cm는 cm끼리 빼요 — 29 − 6 = 23.","그래서 4 m 29 cm − 1 m 6 cm = 3 m 23 cm예요."],"options":[{"t":"3 m 23 cm","correct":true},{"t":"5 m 35 cm","mis":"M2-2-u3-X10"},{"t":"4 m 23 cm","mis":"M2-2-u3-X08"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#6','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','6 m 80 cm − 4 m 50 cm = 2 m 30 cm를 바르게 계산했는지 확인하는 식은 어느 것인가요?',ARRAY['M2-2-u3-X10']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"6 m 80 cm − 4 m 50 cm = 2 m 30 cm를 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"2 m 30 cm + 4 m 50 cm = 6 m 80 cm","correct":true},{"t":"2 m 30 cm − 4 m 50 cm = 6 m 80 cm","mis":"M2-2-u3-X10"},{"t":"6 m 80 cm + 4 m 50 cm = 2 m 30 cm","mis":"M2-2-u3-X10"}],"explanation":["차에 뺀 길이를 더하면 처음 길이가 나와야 해요.","2 m 30 cm + 4 m 50 cm = 6 m 80 cm예요.","처음 길이가 나오니 바르게 계산했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#7','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09']::text[],false,'{"seq":7,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 9 − 1 = 8.","cm는 cm끼리 빼요 — 48 − 3 = 45.","그래서 9 m 48 cm − 1 m 3 cm = 8 m 45 cm예요."],"options":[{"t":"8 m 45 cm","correct":true},{"t":"10 m 51 cm","mis":"M2-2-u3-X10"},{"t":"8 m 18 cm","mis":"M2-2-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#8','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'ox','auto','2 m 50 cm − 1 m 40 cm는 1 m를 100 cm로 바꾸어 250 cm − 140 cm로 구할 수도 있어요.',ARRAY['M2-2-u3-X04']::text[],false,'{"seq":8,"concept":"M2-2-u3-C6","difficulty":2,"kind":"ox","stem":"2 m 50 cm − 1 m 40 cm는 1 m를 100 cm로 바꾸어 250 cm − 140 cm로 구할 수도 있어요.","answer":"O","reason_options":[{"t":"250 cm − 140 cm = 110 cm = 1 m 10 cm로 같은 답이 나오니까","correct":true},{"t":"m와 cm가 함께 있으면 m끼리만 빼야 하니까","mis":"M2-2-u3-X04"}],"mis":"M2-2-u3-X04","explanation":["2 m 50 cm = 250 cm, 1 m 40 cm = 140 cm예요.","250 cm − 140 cm = 110 cm = 1 m 10 cm예요.","m끼리·cm끼리 빼도, cm로 바꾸어 빼도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#9','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'error','auto','친구들이 길이의 차를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X16']::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"error","stem":"친구들이 길이의 차를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"지아 — 「6 m 80 cm − 4 m 50 cm = 2 m 3 cm」","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"수찬 — 「7 m 74 cm − 5 m 32 cm = 2 m 42 cm」","mis":"M2-2-u3-X16"},{"t":"슬기 — 「2 m 50 cm − 1 m 40 cm = 1 m 10 cm」","mis":"M2-2-u3-X16"}],"explanation":["cm끼리 80 − 50 = 30이에요.","6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요.","지아는 30의 0을 떼어 2 m 3 cm라고 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_basic#10','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',3,'mc','auto','9 m 48 cm와 1 m 3 cm의 차보다 긴 길이만 모두 모은 것은 어느 것인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":10,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"9 m 48 cm와 1 m 3 cm의 차보다 긴 길이만 모두 모은 것은 어느 것인가요?","options":[{"t":"8 m 50 cm, 8 m 78 cm, 9 m 14 cm","correct":true},{"t":"8 m 29 cm, 8 m 50 cm, 8 m 78 cm, 9 m 14 cm","mis":"M2-2-u3-X09"},{"t":"9 m 14 cm","mis":"M2-2-u3-X08"}],"explanation":["9 m 48 cm − 1 m 3 cm = 8 m 45 cm예요.","8 m 45 cm보다 긴 것은 8 m 50 cm, 8 m 78 cm, 9 m 14 cm예요.","1 m 3 cm의 3을 30처럼 빼면 8 m 18 cm가 되어 8 m 29 cm까지 고르게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#1','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',2,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u3-C6","difficulty":2,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 7 − 5 = 2.","cm는 cm끼리 빼요 — 74 − 32 = 42.","그래서 7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요."],"answer":["42"],"asset":{"type":"mcm_calc","a":[7,74],"b":[5,32],"op":"-","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#2','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',2,'mc','auto','6 m 80 cm인 색 테이프에서 4 m 50 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],false,'{"seq":2,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"6 m 80 cm인 색 테이프에서 4 m 50 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 80 − 50 = 30.","그래서 6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요."],"options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[6,80],[4,50]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#3','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','2 m 50 cm인 색 테이프에서 얼마를 잘라 쓰면 1 m 10 cm가 남나요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":3,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"2 m 50 cm인 색 테이프에서 얼마를 잘라 쓰면 1 m 10 cm가 남나요?","options":[{"t":"1 m 40 cm","correct":true},{"t":"3 m 60 cm","mis":"M2-2-u3-X10"},{"t":"1 m 4 cm","mis":"M2-2-u3-X11"}],"explanation":["처음 길이에서 남은 길이를 빼면 잘라 쓴 길이예요.","2 m 50 cm − 1 m 10 cm = 1 m 40 cm예요.","1 m 40 cm + 1 m 10 cm = 2 m 50 cm로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#4','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','2 m 50 cm인 나무에서 1 m 40 cm를 사용하고, 남은 나무에서 다시 1 m를 사용했어요. 남은 나무의 길이는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X11']::text[],false,'{"seq":4,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"2 m 50 cm인 나무에서 1 m 40 cm를 사용하고, 남은 나무에서 다시 1 m를 사용했어요. 남은 나무의 길이는 얼마인가요?","options":[{"t":"10 cm","correct":true},{"t":"1 m 10 cm","mis":"M2-2-u3-X16"},{"t":"1 cm","mis":"M2-2-u3-X11"}],"explanation":["처음에 사용하고 남은 나무는 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요.","1 m 10 cm에서 1 m를 다시 쓰면 10 cm가 남아요.","두 번 뺀다는 것을 놓치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#5','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','9 m 48 cm와 1 m 3 cm의 차보다 긴 길이 8 m 29 cm, 8 m 50 cm, 8 m 78 cm, 9 m 14 cm 가운데 가장 짧은 것은 어느 것인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"9 m 48 cm와 1 m 3 cm의 차보다 긴 길이 8 m 29 cm, 8 m 50 cm, 8 m 78 cm, 9 m 14 cm 가운데 가장 짧은 것은 어느 것인가요?","options":[{"t":"8 m 50 cm","correct":true},{"t":"8 m 29 cm","mis":"M2-2-u3-X09"},{"t":"9 m 14 cm","mis":"M2-2-u3-X16"}],"explanation":["두 막대의 차는 8 m 45 cm예요.","8 m 29 cm는 8 m 45 cm보다 짧아서 빼요.","남은 8 m 50 cm, 8 m 78 cm, 9 m 14 cm 가운데 가장 짧은 것은 8 m 50 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#6','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','2 m 50 cm − 1 m 40 cm를 250 cm − 140 cm로 바꾸어 110 cm를 구했어요. 110 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"2 m 50 cm − 1 m 40 cm를 250 cm − 140 cm로 바꾸어 110 cm를 구했어요. 110 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","options":[{"t":"1 m 10 cm","correct":true},{"t":"11 m","mis":"M2-2-u3-X03"},{"t":"1 m 1 cm","mis":"M2-2-u3-X11"}],"explanation":["110 cm = 100 cm + 10 cm예요.","100 cm는 1 m예요.","그래서 110 cm = 1 m 10 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#7','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'blank','auto','7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요. 바르게 구했는지 확인하는 식 2 m 42 cm + (        ) = 7 m 74 cm에 알맞은 길이는 무엇인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X16']::text[],false,'{"seq":7,"concept":"M2-2-u3-C6","difficulty":3,"kind":"blank","stem":"7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요. 바르게 구했는지 확인하는 식 2 m 42 cm + (        ) = 7 m 74 cm에 알맞은 길이는 무엇인가요?","options":[{"t":"5 m 32 cm","correct":true},{"t":"7 m 74 cm","mis":"M2-2-u3-X10"},{"t":"2 m 42 cm","mis":"M2-2-u3-X16"}],"explanation":["차에 뺀 길이를 더하면 처음 길이가 돼요.","뺀 길이는 5 m 32 cm예요.","2 m 42 cm + 5 m 32 cm = 7 m 74 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#8','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'essay','teacher','「친구와 길이의 차 구하기」 쪽지 놀이에서 친구가 「6 m 80 cm − 4 m 50 cm = 2 m 3 cm」라고 썼어요. 맞았는지 확인하고, 틀렸다면 바르게 고친 뒤 덧셈으로 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"「친구와 길이의 차 구하기」 쪽지 놀이에서 친구가 「6 m 80 cm − 4 m 50 cm = 2 m 3 cm」라고 썼어요. 맞았는지 확인하고, 틀렸다면 바르게 고친 뒤 덧셈으로 확인해 보세요.","answer_guide":{"answer":"예: 틀렸다. cm끼리 80 − 50 = 30이므로 2 m 30 cm이다. 2 m 30 cm + 4 m 50 cm = 6 m 80 cm가 되어 맞다.","scoring_points":["틀렸다고 판단했는가","2 m 30 cm로 고쳤는가","차에 뺀 길이를 더해 처음 길이가 나오는지 확인했는가"]},"explanation":["m끼리 2, cm끼리 30이에요.","2 m 3 cm는 30의 0을 뗀 잘못이에요.","2 m 30 cm + 4 m 50 cm = 6 m 80 cm로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#9','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'essay','teacher','2 m 50 cm인 나무에서 1 m 40 cm를 사용했어요. 남은 나무의 길이를 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"2 m 50 cm인 나무에서 1 m 40 cm를 사용했어요. 남은 나무의 길이를 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: ① m는 m끼리 2 − 1 = 1, cm는 cm끼리 50 − 40 = 10이므로 1 m 10 cm이다. ② 250 cm − 140 cm = 110 cm이고 110 cm = 1 m 10 cm이다.","scoring_points":["m끼리·cm끼리 빼는 방법을 썼는가","cm로 바꾸어 빼는 방법을 썼는가","1 m 10 cm를 바르게 구했는가"]},"explanation":["m끼리, cm끼리 빼면 1 m 10 cm예요.","모두 cm로 바꾸어 250 − 140 = 110으로 구해도 돼요.","두 방법 모두 1 m 10 cm예요."],"asset":{"type":"mbar","parts":[[2,50],[1,40]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L05_challenge#10','math',2,2,'u3','L05','tb_g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'mc','auto','9 m 48 cm − 1 m 3 cm를 8 m 18 cm라고 계산한 친구가 있어요. 무엇을 잘못했나요?',ARRAY['M2-2-u3-X10']::text[],false,'{"seq":10,"concept":"M2-2-u3-C6","difficulty":4,"kind":"mc","stem":"9 m 48 cm − 1 m 3 cm를 8 m 18 cm라고 계산한 친구가 있어요. 무엇을 잘못했나요?","options":[{"t":"1 m 3 cm의 3을 30처럼 빼었어요","correct":true},{"t":"9 m와 1 m를 더했어요","mis":"M2-2-u3-X10"},{"t":"48과 3을 더했어요","mis":"M2-2-u3-X10"}],"explanation":["1 m 3 cm의 cm는 3이에요.","cm끼리 48 − 3 = 45 — 바른 답은 8 m 45 cm예요.","48 − 30 = 18로 뺀 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#1','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','동물 연구소에서 「이 바다악어의 몸길이는 약 3 m입니다.」라고 했어요. 3 m가 얼마쯤인지 어림하려면 무엇을 먼저 알면 좋을까요?',ARRAY['M2-2-u3-X17','M2-2-u3-X16']::text[],false,'{"seq":1,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"동물 연구소에서 「이 바다악어의 몸길이는 약 3 m입니다.」라고 했어요. 3 m가 얼마쯤인지 어림하려면 무엇을 먼저 알면 좋을까요?","options":[{"t":"1 m가 얼마쯤인지","correct":true},{"t":"3 cm가 얼마쯤인지","mis":"M2-2-u3-X17"},{"t":"바다악어의 무게가 얼마인지","mis":"M2-2-u3-X16"}],"explanation":["1 m가 얼마쯤인지 알면 기준으로 쓸 수 있어요.","1 m를 세 번 이으면 약 3 m예요.","그래서 1 m의 길이를 먼저 몸으로 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#2','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','교과서의 친구는 1 m를 양팔로 약 1번, 걸음으로 약 2걸음, 뼘으로 약 7뼘이라고 재었어요. 잰 횟수가 가장 많은 몸의 부분은 어느 것인가요?',ARRAY['M2-2-u3-X13']::text[],false,'{"seq":2,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"교과서의 친구는 1 m를 양팔로 약 1번, 걸음으로 약 2걸음, 뼘으로 약 7뼘이라고 재었어요. 잰 횟수가 가장 많은 몸의 부분은 어느 것인가요?","options":[{"t":"뼘","correct":true},{"t":"양팔을 벌린 길이","mis":"M2-2-u3-X13"},{"t":"걸음","mis":"M2-2-u3-X13"}],"explanation":["양팔 1번, 걸음 2번, 뼘 7번이에요.","뼘이 가장 짧아서 가장 많이 재었어요.","단위가 짧을수록 잰 횟수가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#3','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],false,'{"seq":3,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 3 m는 1 m가 3번이니 2걸음씩 3번 — 2 + 2 + 2 = 6이에요.","그래서 약 6걸음쯤이에요."],"options":[{"t":"약 6걸음","correct":true},{"t":"약 5걸음","mis":"M2-2-u3-X14"},{"t":"약 3걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#4','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','끈의 길이를 어림하여 2 m만큼 잘랐어요. 어림한 길이를 바르게 쓴 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X17']::text[],false,'{"seq":4,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"끈의 길이를 어림하여 2 m만큼 잘랐어요. 어림한 길이를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"약 2 m","correct":true},{"t":"2 m","mis":"M2-2-u3-X12"},{"t":"약 2 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 길이는 어림한 길이예요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 2 m라고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#5','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','끈을 어림하여 약 2 m, 약 3 m만큼 잘랐어요. 자로 재어 보니 약 2 m 끈은 1 m 80 cm, 약 3 m 끈은 3 m 10 cm였어요. 어림한 길이보다 더 길게 자른 끈은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X12']::text[],false,'{"seq":5,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"끈을 어림하여 약 2 m, 약 3 m만큼 잘랐어요. 자로 재어 보니 약 2 m 끈은 1 m 80 cm, 약 3 m 끈은 3 m 10 cm였어요. 어림한 길이보다 더 길게 자른 끈은 어느 것인가요?","options":[{"t":"약 3 m로 자른 끈","correct":true},{"t":"약 2 m로 자른 끈","mis":"M2-2-u3-X18"},{"t":"두 끈 모두 어림한 길이와 똑같아요","mis":"M2-2-u3-X12"}],"explanation":["1 m 80 cm는 2 m보다 20 cm 짧아요.","3 m 10 cm는 3 m보다 10 cm 길어요.","그래서 더 길게 자른 끈은 약 3 m로 자른 끈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#6','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','칠판의 긴 쪽을 약 3 m로 어림했어요. 자로 재어 보니 2 m 90 cm였어요. 바르게 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X12']::text[],true,'{"seq":6,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"칠판의 긴 쪽을 약 3 m로 어림했어요. 자로 재어 보니 2 m 90 cm였어요. 바르게 말한 친구는 누구인가요?","options":[{"t":"지아 — 「약 3 m에 가깝게 어림했어.」","correct":true},{"t":"수찬 — 「어림한 길이와 잰 길이가 다르니 틀렸어.」","mis":"M2-2-u3-X12"},{"t":"슬기 — 「어림했으니 「약」을 빼고 3 m라고 써야 해.」","mis":"M2-2-u3-X12"}],"explanation":["2 m 90 cm는 3 m보다 10 cm 짧을 뿐이에요.","어림한 길이는 잰 길이와 조금 달라도 괜찮아요.","어림한 길이에는 「약」을 붙여요."],"variant_rule":{"alt":[{"stem":"선생님 책상의 긴 쪽을 약 2 m로 어림했어요. 자로 재어 보니 1 m 70 cm였어요. 바르게 말한 친구는 누구인가요?","options":[{"t":"세미 — 「1 m를 떠올려 다시 어림해 보면 더 가까워질 거야.」","correct":true},{"t":"연우 — 「어림은 정확해야 하니 다시는 어림하지 말자.」","mis":"M2-2-u3-X12"},{"t":"지아 — 「1 m 70 cm는 약 17 m야.」","mis":"M2-2-u3-X01"}],"explanation":["1 m 70 cm는 2 m보다 30 cm 짧아요.","자로 재어 확인하며 어림을 고쳐 나가요.","1 m 70 cm는 170 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#7','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','교실에서 약 1 m인 물건을 찾아 재었더니 교실 문의 짧은 쪽은 96 cm, 책꽂이의 긴 쪽은 102 cm였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X01']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"교실에서 약 1 m인 물건을 찾아 재었더니 교실 문의 짧은 쪽은 96 cm, 책꽂이의 긴 쪽은 102 cm였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 물건 모두 1 m에 가까워 약 1 m라고 할 수 있어요","correct":true},{"t":"96 cm는 1 m보다 짧으니 약 1 m가 아니에요","mis":"M2-2-u3-X12"},{"t":"102 cm는 약 10 m예요","mis":"M2-2-u3-X01"}],"explanation":["96 cm는 100 cm보다 4 cm 짧아요.","102 cm는 100 cm보다 2 cm 길어요.","둘 다 1 m에 가까우니 약 1 m라고 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#8','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'ox','auto','세 학생이 신발장의 길이를 슬기는 양팔을 벌린 길이로, 세미는 걸음으로, 지아는 뼘으로 재었어요. 잰 횟수가 가장 많은 사람은 슬기예요.',ARRAY['M2-2-u3-X13']::text[],true,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":2,"kind":"ox","stem":"세 학생이 신발장의 길이를 슬기는 양팔을 벌린 길이로, 세미는 걸음으로, 지아는 뼘으로 재었어요. 잰 횟수가 가장 많은 사람은 슬기예요.","answer":"X","reason_options":[{"t":"양팔을 벌린 길이는 뼘보다 길어서 적은 횟수로 잴 수 있으니까","correct":true},{"t":"몸의 부분이 길수록 더 여러 번 재야 하니까","mis":"M2-2-u3-X13"}],"mis":"M2-2-u3-X13","explanation":["양팔을 벌린 길이가 가장 길고, 뼘이 가장 짧아요.","단위가 길수록 잰 횟수는 적어요.","그래서 잰 횟수가 가장 많은 사람은 뼘으로 잰 지아예요."],"variant_rule":{"alt":[{"stem":"세 학생이 신발장의 길이를 양팔·걸음·뼘으로 재었어요. 뼘으로 잰 지아가 잰 횟수가 가장 많아요.","answer":"O","reason_options":[{"t":"뼘이 가장 짧아서 여러 번 재야 하니까","correct":true},{"t":"뼘은 짧아서 조금만 재도 되니까","mis":"M2-2-u3-X13"}],"explanation":["뼘은 양팔이나 걸음보다 짧아요.","짧은 단위로 재면 횟수가 많아요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#9','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'ox','auto','걸음으로 길이를 잴 때는 걸음마다 폭을 크게도 작게도 해도 괜찮아요.',ARRAY['M2-2-u3-X21']::text[],true,'{"seq":9,"concept":"M2-2-u3-C7","difficulty":2,"kind":"ox","stem":"걸음으로 길이를 잴 때는 걸음마다 폭을 크게도 작게도 해도 괜찮아요.","answer":"X","reason_options":[{"t":"걸음 폭이 매번 같아야 몇 걸음인지로 길이를 어림할 수 있으니까","correct":true},{"t":"걸음 수만 세면 폭은 상관없으니까","mis":"M2-2-u3-X21"}],"mis":"M2-2-u3-X21","explanation":["걸음의 폭이 달라지면 같은 「한 걸음」이 아니에요.","양발을 모은 상태에서 한 발을 옮기고 나머지 발을 따라 모아요.","그래서 걸음 폭은 매번 같게 해요."],"variant_rule":{"alt":[{"stem":"1 m를 걸음으로 재면 친구마다 걸음 수가 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 한 걸음의 길이가 다르니까","correct":true},{"t":"1 m는 누구나 똑같이 2걸음이니까","mis":"M2-2-u3-X13"}],"explanation":["한 사람은 약 두 걸음, 다른 사람은 약 세 걸음일 수 있어요.","사람마다 걸음의 길이가 달라요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_basic#10','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',3,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":10,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 4 m는 1 m가 4번이니 2걸음씩 4번 — 2 + 2 + 2 + 2 = 8이에요.","그래서 약 8걸음쯤이에요."],"options":[{"t":"약 8걸음","correct":true},{"t":"약 6걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}],"variant_rule":{"alt":[{"stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 4 m는 1 m가 4번이니 3걸음씩 4번 — 3 + 3 + 3 + 3 = 12예요.","그래서 약 12걸음쯤이에요."],"options":[{"t":"약 12걸음","correct":true},{"t":"약 7걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#1','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',2,'mc','auto','「길이 어림하기 놀이」에서 선생님이 「4 m!」라고 외치자 모둠이 어림하여 도착점에 색 테이프를 붙이고 어림한 방법을 이야기했어요. 그다음에 할 일은 무엇인가요?',ARRAY['M2-2-u3-X12']::text[],false,'{"seq":1,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"「길이 어림하기 놀이」에서 선생님이 「4 m!」라고 외치자 모둠이 어림하여 도착점에 색 테이프를 붙이고 어림한 방법을 이야기했어요. 그다음에 할 일은 무엇인가요?","options":[{"t":"어림한 길이를 자로 재어 확인해요","correct":true},{"t":"색 테이프를 떼고 놀이를 끝내요","mis":"M2-2-u3-X12"},{"t":"「약」을 빼고 4 m라고 써요","mis":"M2-2-u3-X12"}],"explanation":["놀이 순서는 외치기 → 색 테이프 붙이기 → 방법 이야기 → 자로 확인이에요.","자로 재어 보면 내 어림이 얼마나 가까운지 알 수 있어요.","다음 판에는 더 가깝게 어림할 방법을 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#2','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',2,'mc','auto','1 m가 약 7뼘인 친구가 있어요. 이 친구가 약 2 m를 뼘으로 재면 몇 뼘쯤일까요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":2,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 7뼘인 친구가 있어요. 이 친구가 약 2 m를 뼘으로 재면 몇 뼘쯤일까요?","options":[{"t":"약 14뼘","correct":true},{"t":"약 9뼘","mis":"M2-2-u3-X14"},{"t":"약 7뼘","mis":"M2-2-u3-X14"}],"explanation":["1 m가 약 7뼘이에요.","약 2 m는 1 m가 2번이니 7 + 7 = 14예요.","그래서 약 14뼘쯤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#3','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','선생님이 「4 m!」라고 외쳤어요. 1 m가 약 2걸음인 세미와 약 3걸음인 지아가 각각 걸어서 도착점을 정하면 누가 더 많이 걸을까요?',ARRAY['M2-2-u3-X13']::text[],false,'{"seq":3,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"선생님이 「4 m!」라고 외쳤어요. 1 m가 약 2걸음인 세미와 약 3걸음인 지아가 각각 걸어서 도착점을 정하면 누가 더 많이 걸을까요?","options":[{"t":"지아","correct":true},{"t":"세미","mis":"M2-2-u3-X13"},{"t":"둘이 똑같이 걸어요","mis":"M2-2-u3-X13"}],"explanation":["세미는 2걸음씩 4번 — 약 8걸음이에요.","지아는 3걸음씩 4번 — 약 12걸음이에요.","한 걸음이 짧은 지아가 더 많이 걸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#4','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','세 학생이 신발장의 길이를 재었어요. 슬기는 양팔을 벌린 길이로, 세미는 걸음으로, 지아는 뼘으로 재었어요. 잰 횟수가 많은 사람부터 바르게 쓴 것은 어느 것인가요?',ARRAY['M2-2-u3-X13']::text[],false,'{"seq":4,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"세 학생이 신발장의 길이를 재었어요. 슬기는 양팔을 벌린 길이로, 세미는 걸음으로, 지아는 뼘으로 재었어요. 잰 횟수가 많은 사람부터 바르게 쓴 것은 어느 것인가요?","options":[{"t":"지아, 세미, 슬기","correct":true},{"t":"슬기, 세미, 지아","mis":"M2-2-u3-X13"},{"t":"세미, 슬기, 지아","mis":"M2-2-u3-X13"}],"explanation":["뼘 < 걸음 < 양팔을 벌린 길이 순서로 길어요.","짧은 단위일수록 잰 횟수가 많아요.","그래서 지아, 세미, 슬기 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#5','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','1 m를 기준으로 끈 2 m를 어림하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X17']::text[],false,'{"seq":5,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"1 m를 기준으로 끈 2 m를 어림하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 m만큼을 두 번 이어 어림해요","correct":true},{"t":"1 m에 2 cm를 더해요","mis":"M2-2-u3-X14"},{"t":"1 m보다 조금 짧게 잘라요","mis":"M2-2-u3-X17"}],"explanation":["2 m는 1 m가 2번이에요.","1 m를 몸으로 익힌 뒤 두 번 이어요.","어림한 다음에는 자로 재어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#6','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','교실에서 약 1 m인 물건으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":6,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"교실에서 약 1 m인 물건으로 알맞은 것은 어느 것인가요?","options":[{"t":"교실 문의 짧은 쪽","correct":true},{"t":"지우개의 긴 쪽","mis":"M2-2-u3-X17"},{"t":"운동장의 짧은 쪽","mis":"M2-2-u3-X17"}],"explanation":["교실 문의 짧은 쪽은 재어 보니 96 cm였어요.","96 cm는 1 m에 가까워요.","지우개는 몇 cm, 운동장은 몇십 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#7','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','걸음으로 길이를 잴 때 한 걸음은 어떻게 약속하나요?',ARRAY['M2-2-u3-X21']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"걸음으로 길이를 잴 때 한 걸음은 어떻게 약속하나요?","options":[{"t":"양발을 모은 상태에서 한 발을 옮기고 나머지 발을 따라 옮겨 모은 거리","correct":true},{"t":"뛰어서 가장 멀리 간 거리","mis":"M2-2-u3-X21"},{"t":"그때그때 편한 대로 걸은 거리","mis":"M2-2-u3-X21"}],"explanation":["단위가 되는 걸음은 매번 같아야 해요.","양발 모은 상태 → 한 발 옮기기 → 나머지 발 모으기예요.","엄지발가락 끝부터 끝까지의 거리로 약속해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#8','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'essay','teacher','동물 연구소의 바다악어는 몸길이가 약 3 m예요. 1 m를 이용하여 약 3 m를 어림하는 방법을 쓰고, 어림한 뒤에 할 일을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":4,"kind":"essay","stem":"동물 연구소의 바다악어는 몸길이가 약 3 m예요. 1 m를 이용하여 약 3 m를 어림하는 방법을 쓰고, 어림한 뒤에 할 일을 써 보세요.","answer_guide":{"answer":"예: 양팔을 벌린 길이가 약 1 m이므로 양팔을 세 번 벌린 만큼을 약 3 m로 어림한다(또는 1 m가 약 2걸음이므로 약 6걸음). 어림한 다음 줄자로 재어 확인한다.","scoring_points":["1 m를 기준으로 삼았는가","1 m가 3번쯤이라고 어림했는가","자로 재어 확인한다고 썼는가"]},"explanation":["1 m를 몸의 부분으로 익혀요.","1 m가 세 번이면 약 3 m예요.","어림한 길이는 자로 재어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#9','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'essay','teacher','세 학생이 같은 신발장을 양팔을 벌린 길이, 걸음, 뼘으로 재었더니 잰 횟수가 서로 달랐어요. 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C7","difficulty":4,"kind":"essay","stem":"세 학생이 같은 신발장을 양팔을 벌린 길이, 걸음, 뼘으로 재었더니 잰 횟수가 서로 달랐어요. 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 양팔을 벌린 길이, 걸음, 뼘의 길이가 서로 다르기 때문이다. 단위가 긴 양팔은 적은 횟수로, 단위가 짧은 뼘은 많은 횟수로 잰다.","scoring_points":["몸의 부분마다 길이가 다르다고 썼는가","단위가 길수록 횟수가 적다고 썼는가","뼘으로 잰 횟수가 가장 많다고 썼는가"]},"explanation":["몸의 부분마다 길이가 달라요.","단위가 길면 적게, 짧으면 많이 재요.","그래서 잰 횟수가 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L06_challenge#10','math',2,2,'u3','L06','tb_g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'mc','auto','1 m가 약 7뼘인 지아가 끈을 약 3 m만큼 자르려고 해요. 뼘으로 몇 뼘쯤 재면 될까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],false,'{"seq":10,"concept":"M2-2-u3-C7","difficulty":4,"kind":"mc","stem":"1 m가 약 7뼘인 지아가 끈을 약 3 m만큼 자르려고 해요. 뼘으로 몇 뼘쯤 재면 될까요?","options":[{"t":"약 21뼘","correct":true},{"t":"약 10뼘","mis":"M2-2-u3-X14"},{"t":"약 3뼘","mis":"M2-2-u3-X13"}],"explanation":["1 m가 약 7뼘이에요.","약 3 m는 1 m가 3번이니 7 + 7 + 7 = 21이에요.","그래서 약 21뼘쯤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#1','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','축구 골대의 긴 쪽은 약 5 m예요. 약 5 m의 2배 정도로 어림하면 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":1,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"축구 골대의 긴 쪽은 약 5 m예요. 약 5 m의 2배 정도로 어림하면 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 5 m","mis":"M2-2-u3-X14"}],"explanation":["2배 정도는 같은 길이가 두 번이에요.","5 + 5 = 10이에요.","그래서 약 10 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#2','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','약 2 m를 어림한 것을 이용하여 5배 정도로 어림했어요. 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":2,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"약 2 m를 어림한 것을 이용하여 5배 정도로 어림했어요. 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 25 m","mis":"M2-2-u3-X14"}],"explanation":["5배 정도는 같은 길이가 다섯 번이에요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 약 10 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#3','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','운동장의 짧은 쪽을 한쪽 끝에서 축구 골대까지 약 10 m, 축구 골대 약 5 m, 축구 골대에서 나머지 한쪽 끝까지 약 10 m로 나누어 어림했어요. 전체 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":3,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"운동장의 짧은 쪽을 한쪽 끝에서 축구 골대까지 약 10 m, 축구 골대 약 5 m, 축구 골대에서 나머지 한쪽 끝까지 약 10 m로 나누어 어림했어요. 전체 거리는 약 몇 m인가요?","options":[{"t":"약 25 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X14"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 길이를 모두 더해요.","10 + 5 + 10 = 25예요.","그래서 전체 거리는 약 25 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#4','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'ox','auto','운동장의 짧은 쪽 길이는 몇 부분으로 나누어 어림한 뒤 모두 더해도 돼요.',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":4,"concept":"M2-2-u3-C8","difficulty":1,"kind":"ox","stem":"운동장의 짧은 쪽 길이는 몇 부분으로 나누어 어림한 뒤 모두 더해도 돼요.","answer":"O","reason_options":[{"t":"부분마다 어림한 길이를 더하면 전체 길이가 되니까","correct":true},{"t":"긴 거리는 한 번에 눈으로만 정해야 하니까","mis":"M2-2-u3-X14"}],"mis":"M2-2-u3-X14","explanation":["긴 거리는 한 번에 짐작하기 어려워요.","몇 부분으로 나누면 부분마다 어림하기 쉬워요.","부분의 길이를 모두 더하면 전체 길이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#5','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','운동장의 짧은 쪽에 거리 표시기가 박혀 있고, 표시기 사이 간격 약 1 m가 25칸이에요. 운동장의 짧은 쪽은 약 몇 m인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":5,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"운동장의 짧은 쪽에 거리 표시기가 박혀 있고, 표시기 사이 간격 약 1 m가 25칸이에요. 운동장의 짧은 쪽은 약 몇 m인가요?","options":[{"t":"약 25 m","correct":true},{"t":"약 26 m","mis":"M2-2-u3-X15"},{"t":"약 1 m","mis":"M2-2-u3-X14"}],"explanation":["약 1 m 간격이 25칸이에요.","1 m가 25번이니 약 25 m예요.","같은 간격이 몇 칸인지 세어 어림했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#6','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'sa','auto','한 칸이 약 5 m인 간격이 2개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M2-2-u3-C8","difficulty":2,"kind":"sa","stem":"한 칸이 약 5 m인 간격이 2개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.","explanation":["약 5 m가 2번 있어요.","5 + 5 = 10이에요.","그래서 모두 약 10 m예요."],"answer":["10"],"asset":{"type":"est_row","seg":5,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#7','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요?","explanation":["약 2 m가 5번 있어요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 모두 약 10 m예요."],"options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 8 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#8','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'match','auto','어림하는 방법과 알맞은 예를 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C8","difficulty":2,"kind":"match","stem":"어림하는 방법과 알맞은 예를 이으세요.","pairs":[{"l":"기준이 되는 길이로 어림하기","r":"약 5 m의 2배 정도로 10 m를 어림해요"},{"l":"몇 부분으로 나누어 어림한 뒤 더하기","r":"약 10 m, 약 5 m, 약 10 m를 더해 약 25 m"},{"l":"같은 간격이 몇 개인지 세기","r":"약 1 m 간격의 표시기 사이가 몇 칸인지 세어요"}],"mis":"M2-2-u3-X14","explanation":["아는 길이를 기준으로 몇 배쯤인지 보는 방법이에요.","전체를 덩어리로 나누어 어림하고 더하는 방법이에요.","같은 간격이 몇 개인지 세는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#9','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','두 깃발 사이의 거리가 약 5 m가 되도록 깃발을 놓으려고 해요. 양팔을 벌린 길이가 약 1 m라면 첫 깃발에서 양팔을 몇 번쯤 벌린 곳에 다른 깃발을 놓으면 될까요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":9,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"두 깃발 사이의 거리가 약 5 m가 되도록 깃발을 놓으려고 해요. 양팔을 벌린 길이가 약 1 m라면 첫 깃발에서 양팔을 몇 번쯤 벌린 곳에 다른 깃발을 놓으면 될까요?","options":[{"t":"약 5번","correct":true},{"t":"약 4번","mis":"M2-2-u3-X15"},{"t":"약 10번","mis":"M2-2-u3-X14"}],"explanation":["양팔을 벌린 길이는 약 1 m예요.","약 5 m는 1 m가 5번이에요.","그래서 양팔을 약 5번 벌린 곳에 깃발을 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_basic#10','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',3,'mc','auto','운동장의 짧은 쪽에 나무가 약 2 m 간격으로 한 줄로 13그루 심어져 있어요. 첫 나무에서 마지막 나무까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":10,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"운동장의 짧은 쪽에 나무가 약 2 m 간격으로 한 줄로 13그루 심어져 있어요. 첫 나무에서 마지막 나무까지는 약 몇 m인가요?","options":[{"t":"약 24 m","correct":true},{"t":"약 26 m","mis":"M2-2-u3-X15"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["나무가 13그루이면 사이 간격은 12개예요.","약 2 m씩 12번이니 약 24 m예요.","나무 수만큼 13번 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#1','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',2,'mc','auto','「20 m도 어림해 볼까?」 — 약 10 m를 어림한 것을 이용하면 약 20 m는 약 10 m의 몇 배 정도인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":1,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"「20 m도 어림해 볼까?」 — 약 10 m를 어림한 것을 이용하면 약 20 m는 약 10 m의 몇 배 정도인가요?","options":[{"t":"2배","correct":true},{"t":"10배","mis":"M2-2-u3-X14"},{"t":"20배","mis":"M2-2-u3-X14"}],"explanation":["10 + 10 = 20이에요.","약 10 m가 두 번이면 약 20 m예요.","그래서 2배 정도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#2','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 5개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],false,'{"seq":2,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 5개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 5번 있어요.","5 + 5 + 5 + 5 + 5 = 25예요.","그래서 모두 약 25 m예요."],"options":[{"t":"약 25 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X14"},{"t":"약 20 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#3','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','『수학익힘』 그림에서 그네의 길이는 약 4 m, 울타리 한 칸의 길이는 약 2 m예요. 왼쪽 나무에서 그네까지 울타리가 세 칸, 그네에서 오른쪽 나무까지 울타리가 세 칸이에요. 두 나무 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":3,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"『수학익힘』 그림에서 그네의 길이는 약 4 m, 울타리 한 칸의 길이는 약 2 m예요. 왼쪽 나무에서 그네까지 울타리가 세 칸, 그네에서 오른쪽 나무까지 울타리가 세 칸이에요. 두 나무 사이의 거리는 약 몇 m인가요?","options":[{"t":"약 16 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X14"},{"t":"약 10 m","mis":"M2-2-u3-X14"}],"explanation":["울타리 세 칸은 2 + 2 + 2 = 6 — 약 6 m예요.","6 + 4 + 6 = 16이에요.","그래서 두 나무 사이는 약 16 m예요 — 그네 길이를 빠뜨리면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#4','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','운동장의 짧은 쪽을 나누어 어림해 약 25 m, 나무 간격을 세어 약 24 m로 어림했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X14']::text[],false,'{"seq":4,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"운동장의 짧은 쪽을 나누어 어림해 약 25 m, 나무 간격을 세어 약 24 m로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 방법 모두 운동장 짧은 쪽의 길이에 가깝게 어림했어요","correct":true},{"t":"어림한 값이 다르니 하나는 틀렸어요","mis":"M2-2-u3-X12"},{"t":"약 25 m와 약 24 m를 더해 약 49 m예요","mis":"M2-2-u3-X14"}],"explanation":["어림한 길이는 방법에 따라 조금 다를 수 있어요.","약 25 m와 약 24 m는 아주 가까워요.","자로 재어 확인하면 어느 어림이 더 가까운지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#5','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','출발선부터 바닥에 약 1 m 길이의 무늬가 이어져 있어요. 출발선에서 무늬 10개가 끝나는 곳까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":5,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"출발선부터 바닥에 약 1 m 길이의 무늬가 이어져 있어요. 출발선에서 무늬 10개가 끝나는 곳까지는 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 9 m","mis":"M2-2-u3-X15"},{"t":"약 11 m","mis":"M2-2-u3-X15"}],"explanation":["무늬 하나가 약 1 m예요.","무늬 10개를 이으면 1 m가 10번이에요.","그래서 약 10 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#6','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'error','auto','출발선에서부터 10 m인 거리를 어림한 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C8","difficulty":3,"kind":"error","stem":"출발선에서부터 10 m인 거리를 어림한 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연우 — 「약 2 m를 2번 이어서 10 m를 어림했어.」","correct":true,"mis_target":"M2-2-u3-X14"},{"t":"지아 — 「약 5 m의 2배 정도로 어림했어.」","mis":"M2-2-u3-X16"},{"t":"수찬 — 「약 2 m를 어림한 것을 이용해 5배 정도로 어림했어.」","mis":"M2-2-u3-X16"}],"explanation":["약 2 m를 2번 이으면 약 4 m예요.","10 m가 되려면 약 2 m를 5번 이어야 해요.","그래서 연우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#7','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','두 깃발 사이의 거리가 약 5 m가 되도록 깃발 3개를 같은 간격으로 한 줄로 놓았어요. 첫 깃발과 마지막 깃발 사이는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"두 깃발 사이의 거리가 약 5 m가 되도록 깃발 3개를 같은 간격으로 한 줄로 놓았어요. 첫 깃발과 마지막 깃발 사이는 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 15 m","mis":"M2-2-u3-X15"},{"t":"약 5 m","mis":"M2-2-u3-X15"}],"explanation":["깃발이 3개이면 사이 간격은 2개예요.","약 5 m씩 2번이니 약 10 m예요.","깃발 수만큼 3번 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#8','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'essay','teacher','운동장의 짧은 쪽 길이를 어림하는 방법을 두 가지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C8","difficulty":4,"kind":"essay","stem":"운동장의 짧은 쪽 길이를 어림하는 방법을 두 가지 설명해 보세요.","answer_guide":{"answer":"예: ① 한쪽 끝에서 축구 골대까지 약 10 m, 골대 약 5 m, 골대에서 다른 끝까지 약 10 m로 나누어 더하면 약 25 m이다. ② 약 2 m 간격으로 심은 나무 13그루 사이 간격 12개를 세면 약 24 m이다.","scoring_points":["몇 부분으로 나누어 더하는 방법을 썼는가","같은 간격을 세거나 기준 길이로 어림하는 방법을 썼는가","어림한 길이에 「약」을 붙이거나 자로 확인한다고 썼는가"]},"explanation":["몇 부분으로 나누어 어림하고 더해요.","같은 간격이 몇 개인지 세어도 돼요.","아는 길이(5 m, 10 m)를 기준 삼아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#9','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'essay','teacher','출발선에서부터 10 m인 거리를 어림하는 방법을 쓰고, 그 방법으로 20 m는 어떻게 어림할 수 있을지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C8","difficulty":4,"kind":"essay","stem":"출발선에서부터 10 m인 거리를 어림하는 방법을 쓰고, 그 방법으로 20 m는 어떻게 어림할 수 있을지 써 보세요.","answer_guide":{"answer":"예: 약 5 m를 어림하고 그 2배 정도로 10 m를 어림한다. 20 m는 어림한 10 m의 2배 정도(또는 5 m의 4배 정도)로 어림하고 자로 재어 확인한다.","scoring_points":["5 m나 2 m를 기준으로 10 m를 어림했는가","10 m를 기준으로 20 m를 어림했는가","자로 재어 확인한다고 썼는가"]},"explanation":["1 m ⇨ 5 m ⇨ 10 m로 기준을 늘려요.","20 m는 10 m의 2배 정도예요.","어림한 다음 자로 재어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_L07_challenge#10','math',2,2,'u3','L07','tb_g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'mc','auto','두 나무 사이의 거리가 약 16 m이고, 가운데에 있는 그네의 길이는 약 4 m예요. 왼쪽 나무에서 그네까지와 그네에서 오른쪽 나무까지의 거리가 같다면 왼쪽 나무에서 그네까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":10,"concept":"M2-2-u3-C8","difficulty":4,"kind":"mc","stem":"두 나무 사이의 거리가 약 16 m이고, 가운데에 있는 그네의 길이는 약 4 m예요. 왼쪽 나무에서 그네까지와 그네에서 오른쪽 나무까지의 거리가 같다면 왼쪽 나무에서 그네까지는 약 몇 m인가요?","options":[{"t":"약 6 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X14"},{"t":"약 8 m","mis":"M2-2-u3-X14"}],"explanation":["16 m에서 그네 4 m를 빼면 12 m가 남아요.","남은 12 m를 양쪽이 똑같이 나누면 6 m씩이에요.","6 + 4 + 6 = 16으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#1','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C1',1,'sa','auto','100 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"100 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","1 cm가 100번 모이면 100 cm — 이 길이를 1 m라고 해요.","그래서 100 cm = 1 m예요."],"answer":["1"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#2','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',1,'mc','auto','248 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],false,'{"seq":2,"concept":"M2-2-u3-C2","difficulty":1,"kind":"mc","stem":"248 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["248 cm는 200 cm와 48 cm예요.","200 cm는 2 m예요.","그래서 248 cm = 2 m 48 cm예요."],"options":[{"t":"2 m 48 cm","correct":true},{"t":"24 m 8 cm","mis":"M2-2-u3-X03"},{"t":"2 m 4 cm","mis":"M2-2-u3-X11"},{"t":"48 m 2 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#3','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',1,'mc','auto','책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],false,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 130이니 130 cm예요.","130 cm = 100 cm + 30 cm = 1 m 30 cm예요."],"options":[{"t":"1 m 30 cm","correct":true},{"t":"13 m","mis":"M2-2-u3-X03"},{"t":"1 m 31 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":130,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#4','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',1,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 4 + 2 = 6.","cm는 cm끼리 더해요 — 35 + 43 = 78.","그래서 4 m 35 cm + 2 m 43 cm = 6 m 78 cm예요."],"options":[{"t":"6 m 78 cm","correct":true},{"t":"2 m 8 cm","mis":"M2-2-u3-X10"},{"t":"7 m 78 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[4,35],"b":[2,43],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#5','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',1,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 빼요 — 5 − 3 = 2.","cm는 cm끼리 빼요 — 64 − 22 = 42.","그래서 5 m 64 cm − 3 m 22 cm = 2 m 42 cm예요."],"options":[{"t":"2 m 42 cm","correct":true},{"t":"8 m 86 cm","mis":"M2-2-u3-X10"},{"t":"3 m 42 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[5,64],"b":[3,22],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#6','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',1,'mc','auto','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 4 m 26 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 4 m 26 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?","options":[{"t":"2 m 62 cm","correct":true},{"t":"11 m 14 cm","mis":"M2-2-u3-X10"},{"t":"3 m 62 cm","mis":"M2-2-u3-X08"}],"explanation":["전체 막대에서 한 도막을 빼면 다른 도막이에요.","m끼리 6 − 4 = 2, cm끼리 88 − 26 = 62예요.","두 길이를 더하면 안 돼요 — 다른 도막은 2 m 62 cm예요."],"asset":{"type":"mbar","parts":[[6,88],[4,26]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#7','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',1,'mc','auto','학생들이 버스를 타려고 줄을 섰어요. 선생님이 「앞 사람과의 간격이 1 m씩 되게 줄을 서세요.」라고 했어요. 줄을 선 학생이 8명일 때 가장 앞에 있는 학생과 가장 뒤에 있는 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"학생들이 버스를 타려고 줄을 섰어요. 선생님이 「앞 사람과의 간격이 1 m씩 되게 줄을 서세요.」라고 했어요. 줄을 선 학생이 8명일 때 가장 앞에 있는 학생과 가장 뒤에 있는 학생 사이의 거리는 약 몇 m인가요?","options":[{"t":"약 7 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"explanation":["학생 8명 사이의 간격은 7개예요.","간격이 1 m씩이니 약 7 m예요.","학생 수만큼 8 m라고 하면 안 돼요 — 간격을 세어요."],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#8','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C7',1,'mc','auto','「우리 반 사물함의 높이는 약 1 m입니다.」처럼 1 m, 3 m, 5 m 가운데 하나를 골라 문장을 만들어요. 「자동차의 길이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"「우리 반 사물함의 높이는 약 1 m입니다.」처럼 1 m, 3 m, 5 m 가운데 하나를 골라 문장을 만들어요. 「자동차의 길이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?","options":[{"t":"5 m","correct":true},{"t":"5 cm","mis":"M2-2-u3-X17"},{"t":"50 m","mis":"M2-2-u3-X17"}],"explanation":["자동차는 어른 키의 두세 배보다 길어요.","1 m를 다섯 번 이은 만큼이에요.","그래서 자동차의 길이는 약 5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#9','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',2,'mc','auto','「가로는 2 m 75 cm, 세로는 1 m 30 cm이니까 가로가 ▢ 더 길구나.」 ▢에 알맞은 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"「가로는 2 m 75 cm, 세로는 1 m 30 cm이니까 가로가 ▢ 더 길구나.」 ▢에 알맞은 길이는 얼마인가요?","options":[{"t":"1 m 45 cm","correct":true},{"t":"4 m 5 cm","mis":"M2-2-u3-X10"},{"t":"1 m 55 cm","mis":"M2-2-u3-X08"}],"explanation":["가로가 얼마나 더 긴지는 차로 구해요.","m끼리 2 − 1 = 1, cm끼리 75 − 30 = 45예요.","그래서 가로가 1 m 45 cm 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#10','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#11','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',2,'mc','auto','사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],false,'{"seq":11,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["사물함의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."],"options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#12','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',2,'mc','auto','4 m 26 cm + 1 m 60 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":12,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"4 m 26 cm + 1 m 60 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 4 + 1 = 5.","cm는 cm끼리 더해요 — 26 + 60 = 86.","그래서 4 m 26 cm + 1 m 60 cm = 5 m 86 cm예요."],"options":[{"t":"5 m 86 cm","correct":true},{"t":"3 m 34 cm","mis":"M2-2-u3-X10"},{"t":"6 m 86 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#13','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',2,'mc','auto','7 m 74 cm − 5 m 32 cm는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],false,'{"seq":13,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"7 m 74 cm − 5 m 32 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 7 − 5 = 2.","cm는 cm끼리 빼요 — 74 − 32 = 42.","그래서 7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요."],"options":[{"t":"2 m 42 cm","correct":true},{"t":"3 m 42 cm","mis":"M2-2-u3-X08"},{"t":"2 m 52 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#14','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],false,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 3 m는 1 m가 3번이니 2걸음씩 3번 — 2 + 2 + 2 = 6이에요.","그래서 약 6걸음쯤이에요."],"options":[{"t":"약 6걸음","correct":true},{"t":"약 5걸음","mis":"M2-2-u3-X14"},{"t":"약 3걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#15','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',2,'mc','auto','축구 골대의 긴 쪽 약 5 m를 기준으로, 약 5 m의 2배 정도면 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"축구 골대의 긴 쪽 약 5 m를 기준으로, 약 5 m의 2배 정도면 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["2배 정도는 두 번이에요.","5 + 5 = 10이에요.","그래서 약 10 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#16','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',2,'ox','auto','줄자로 잴 때는 물건의 한끝을 줄자의 눈금 0에 맞춰요.',ARRAY['M2-2-u3-X06']::text[],false,'{"seq":16,"concept":"M2-2-u3-C4","difficulty":2,"kind":"ox","stem":"줄자로 잴 때는 물건의 한끝을 줄자의 눈금 0에 맞춰요.","answer":"O","reason_options":[{"t":"그래야 다른 끝의 눈금이 바로 길이가 되니까","correct":true},{"t":"눈금 1부터 재야 바르게 잴 수 있으니까","mis":"M2-2-u3-X06"}],"mis":"M2-2-u3-X06","explanation":["한끝을 눈금 0에 맞춰요.","다른 끝이 닿은 눈금이 길이예요.","그래서 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#17','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',3,'mc','auto','책상의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 책상의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],false,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"책상의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 책상의 길이는 몇 cm인가요?","explanation":["책상의 한끝은 눈금 2, 다른 끝은 눈금 142에 있어요.","142 − 2 = 140이니 140 cm예요.","끝 눈금 142를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"options":[{"t":"140 cm","correct":true},{"t":"142 cm","mis":"M2-2-u3-X06"},{"t":"141 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":140,"label":"책상","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#18','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',3,'mc','auto','친구가 2 m 24 cm + 7 m 5 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X10']::text[],false,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 2 m 24 cm + 7 m 5 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?","options":[{"t":"9 m 29 cm","correct":true},{"t":"9 m 74 cm","mis":"M2-2-u3-X09"},{"t":"5 m 19 cm","mis":"M2-2-u3-X10"}],"explanation":["같은 단위끼리 줄을 맞추어 써요.","cm끼리 24 + 5 = 29, m끼리 2 + 7 = 9예요.","바른 답은 9 m 29 cm — 친구는 한 자리 수 cm를 몇십처럼 계산했어요."],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"both","said":[9,74]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#19','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',3,'mc','auto','248 cm, 2 m 5 cm, 2 m 50 cm 가운데 가장 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":19,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"248 cm, 2 m 5 cm, 2 m 50 cm 가운데 가장 긴 것은 어느 것인가요?","options":[{"t":"2 m 50 cm","correct":true},{"t":"248 cm","mis":"M2-2-u3-X18"},{"t":"2 m 5 cm","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 248 cm, 205 cm, 250 cm예요.","250 cm가 가장 길어요.","보이는 수 248만 보면 안 돼요 — 2 m 50 cm가 가장 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#20','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',3,'mc','auto','범고래의 몸길이는 약 6 m 50 cm, 바다거북의 몸길이는 약 1 m 30 cm예요. 몸길이가 가장 긴 동물과 가장 짧은 동물의 몸길이의 차는 약 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"범고래의 몸길이는 약 6 m 50 cm, 바다거북의 몸길이는 약 1 m 30 cm예요. 몸길이가 가장 긴 동물과 가장 짧은 동물의 몸길이의 차는 약 얼마인가요?","options":[{"t":"약 5 m 20 cm","correct":true},{"t":"약 7 m 80 cm","mis":"M2-2-u3-X10"},{"t":"약 5 m 30 cm","mis":"M2-2-u3-X08"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 6 − 1 = 5, cm끼리 50 − 30 = 20이에요.","그래서 약 5 m 20 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#21','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',3,'mc','auto','수찬이의 키는 1 m 20 cm예요. 바다거북(약 1 m 30 cm), 바다표범(약 1 m 80 cm), 돌고래(약 2 m 20 cm) 가운데 수찬이의 키와 몸길이가 가장 비슷한 동물은 무엇인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X17']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"수찬이의 키는 1 m 20 cm예요. 바다거북(약 1 m 30 cm), 바다표범(약 1 m 80 cm), 돌고래(약 2 m 20 cm) 가운데 수찬이의 키와 몸길이가 가장 비슷한 동물은 무엇인가요?","options":[{"t":"바다거북","correct":true},{"t":"돌고래","mis":"M2-2-u3-X18"},{"t":"바다표범","mis":"M2-2-u3-X17"}],"explanation":["1 m 20 cm와 견주면 바다거북은 10 cm, 바다표범은 60 cm, 돌고래는 1 m 더 길어요.","cm의 수 20이 같다고 돌고래를 고르면 안 돼요 — m부터 봐요.","그래서 바다거북이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#22','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',3,'mc','auto','그네의 길이는 약 4 m, 울타리 한 칸의 길이는 약 2 m예요. 왼쪽 나무에서 그네까지 울타리가 세 칸, 그네에서 오른쪽 나무까지 울타리가 세 칸이에요. 나무와 나무 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"그네의 길이는 약 4 m, 울타리 한 칸의 길이는 약 2 m예요. 왼쪽 나무에서 그네까지 울타리가 세 칸, 그네에서 오른쪽 나무까지 울타리가 세 칸이에요. 나무와 나무 사이의 거리는 약 몇 m인가요?","options":[{"t":"약 16 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X14"},{"t":"약 10 m","mis":"M2-2-u3-X14"}],"explanation":["울타리 세 칸은 약 6 m예요.","6 + 4 + 6 = 16이에요.","그래서 나무와 나무 사이는 약 16 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#23','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',4,'essay','teacher','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이를 구하고, 두 길이를 더하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이를 구하고, 두 길이를 더하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 다른 도막은 전체에서 한 도막을 뺀 길이이다. 6 m 88 cm − 4 m 26 cm = 2 m 62 cm이다. 두 길이를 더하면 전체보다 긴 길이가 되어 다른 도막이 될 수 없다.","scoring_points":["뺄셈으로 구해야 한다고 썼는가","2 m 62 cm를 구했는가","더하면 전체보다 길어진다는 까닭을 썼는가"]},"explanation":["전체와 한 부분을 알면 나머지 부분은 차로 구해요.","m끼리 2, cm끼리 62 — 2 m 62 cm예요.","2 m 62 cm + 4 m 26 cm = 6 m 88 cm로 확인해요."],"asset":{"type":"mbar","parts":[[6,88],[4,26]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#24','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',4,'essay','teacher','동물 몸길이 사전에서 몸길이가 가장 긴 동물과 가장 짧은 동물을 찾고, 두 동물의 몸길이의 차를 구하는 방법을 설명해 보세요. (바다표범 약 1 m 80 cm · 돌고래 약 2 m 20 cm · 범고래 약 6 m 50 cm · 바다거북 약 1 m 30 cm · 바다악어 약 4 m 80 cm · 백상아리 약 4 m 30 cm)','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"동물 몸길이 사전에서 몸길이가 가장 긴 동물과 가장 짧은 동물을 찾고, 두 동물의 몸길이의 차를 구하는 방법을 설명해 보세요. (바다표범 약 1 m 80 cm · 돌고래 약 2 m 20 cm · 범고래 약 6 m 50 cm · 바다거북 약 1 m 30 cm · 바다악어 약 4 m 80 cm · 백상아리 약 4 m 30 cm)","answer_guide":{"answer":"예: m부터 견주면 가장 긴 동물은 범고래(약 6 m 50 cm), 가장 짧은 동물은 바다거북(약 1 m 30 cm)이다. m끼리 6 − 1 = 5, cm끼리 50 − 30 = 20이므로 차는 약 5 m 20 cm이다.","scoring_points":["범고래와 바다거북을 바르게 찾았는가","m끼리·cm끼리 뺐는가","약 5 m 20 cm를 구했는가"]},"explanation":["몸길이는 m부터, 같으면 cm를 견주어요.","가장 긴 범고래와 가장 짧은 바다거북의 차를 구해요.","약 6 m 50 cm − 약 1 m 30 cm = 약 5 m 20 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_a#25','math',2,2,'u3','','tb_g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',4,'mc','auto','학생들이 앞 사람과의 간격이 약 1 m씩 되게 버스를 타려고 줄을 섰어요. 가장 앞의 학생과 가장 뒤의 학생 사이의 거리가 약 7 m라면 줄을 선 학생은 몇 명인가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":25,"concept":"M2-2-u3-C8","difficulty":4,"kind":"mc","stem":"학생들이 앞 사람과의 간격이 약 1 m씩 되게 버스를 타려고 줄을 섰어요. 가장 앞의 학생과 가장 뒤의 학생 사이의 거리가 약 7 m라면 줄을 선 학생은 몇 명인가요?","options":[{"t":"8명","correct":true},{"t":"7명","mis":"M2-2-u3-X15"},{"t":"6명","mis":"M2-2-u3-X15"}],"explanation":["간격 하나가 약 1 m이니 약 7 m는 간격 7개예요.","학생 수는 간격 수보다 하나 많아요.","그래서 8명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#1','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C1',1,'sa','auto','200 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"200 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","200 cm는 100 cm가 2번이에요.","그래서 200 cm = 2 m예요."],"answer":["2"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#2','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',1,'sa','auto','2 m 5 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"2 m 5 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["2 m는 200 cm예요.","200 cm와 5 cm를 모으면 205 cm예요.","cm가 한 자리 수라 십의 자리에 0을 써서 205예요 — 25가 아니에요."],"answer":["205"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#3','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',1,'sa','auto','책장의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"책장의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 130이니 130 cm예요.","130 cm는 1 m 30 cm라고도 나타내요."],"answer":["130"],"asset":{"type":"tape","len":130,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#4','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',1,'mc','auto','3 m 25 cm + 1 m 30 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 25 cm + 1 m 30 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 1 = 4.","cm는 cm끼리 더해요 — 25 + 30 = 55.","그래서 3 m 25 cm + 1 m 30 cm = 4 m 55 cm예요."],"options":[{"t":"4 m 55 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"5 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#5','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',1,'mc','auto','4 m 58 cm − 2 m 25 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"4 m 58 cm − 2 m 25 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 2 = 2.","cm는 cm끼리 빼요 — 58 − 25 = 33.","그래서 4 m 58 cm − 2 m 25 cm = 2 m 33 cm예요."],"options":[{"t":"2 m 33 cm","correct":true},{"t":"6 m 83 cm","mis":"M2-2-u3-X10"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#6','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',1,'mc','auto','길이가 9 m 48 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 1 m 3 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"길이가 9 m 48 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 1 m 3 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?","options":[{"t":"8 m 45 cm","correct":true},{"t":"10 m 51 cm","mis":"M2-2-u3-X10"},{"t":"8 m 18 cm","mis":"M2-2-u3-X08"}],"explanation":["전체 막대에서 한 도막을 빼면 다른 도막이에요.","m끼리 9 − 1 = 8, cm끼리 48 − 3 = 45예요.","두 길이를 더하면 안 돼요 — 다른 도막은 8 m 45 cm예요."],"asset":{"type":"mbar","parts":[[9,48],[1,3]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#7','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',1,'sa','auto','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":1,"kind":"sa","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요? 숫자로 쓰세요.","explanation":["학생이 8명이면 사이 간격은 7개예요.","약 1 m씩 7번이니 약 7 m예요.","사람 수만큼 8번 더하면 안 돼요 — 간격을 세어요."],"answer":["7"],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#8','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',1,'mc','auto','「보기」의 문장 「우리 반 사물함의 높이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"「보기」의 문장 「우리 반 사물함의 높이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?","options":[{"t":"1 m","correct":true},{"t":"1 cm","mis":"M2-2-u3-X17"},{"t":"10 m","mis":"M2-2-u3-X17"}],"explanation":["사물함의 높이는 양팔을 벌린 길이쯤이에요.","양팔을 벌린 길이는 약 1 m예요.","그래서 사물함의 높이는 약 1 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#9','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',2,'mc','auto','칠판의 긴 쪽은 2 m 90 cm, 선생님 책상의 긴 쪽은 1 m 70 cm예요. 칠판의 긴 쪽이 얼마나 더 긴가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"칠판의 긴 쪽은 2 m 90 cm, 선생님 책상의 긴 쪽은 1 m 70 cm예요. 칠판의 긴 쪽이 얼마나 더 긴가요?","options":[{"t":"1 m 20 cm","correct":true},{"t":"4 m 60 cm","mis":"M2-2-u3-X10"},{"t":"1 m 30 cm","mis":"M2-2-u3-X08"}],"explanation":["얼마나 더 긴지는 차로 구해요.","m끼리 2 − 1 = 1, cm끼리 90 − 70 = 20이에요.","그래서 1 m 20 cm 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#10','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#11','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',2,'sa','auto','선생님 책상의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"선생님 책상의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["선생님 책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 180이니 180 cm예요.","180 cm는 1 m 80 cm라고도 나타내요."],"answer":["180"],"asset":{"type":"tape","len":180,"label":"선생님 책상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#12','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',2,'mc','auto','2 m 24 cm + 7 m 5 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":12,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"2 m 24 cm + 7 m 5 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 2 + 7 = 9.","cm는 cm끼리 더해요 — 24 + 5 = 29.","그래서 2 m 24 cm + 7 m 5 cm = 9 m 29 cm예요."],"options":[{"t":"9 m 29 cm","correct":true},{"t":"5 m 19 cm","mis":"M2-2-u3-X10"},{"t":"9 m 74 cm","mis":"M2-2-u3-X09"},{"t":"10 m 29 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#13','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',2,'mc','auto','4 m 29 cm − 1 m 6 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":13,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"4 m 29 cm − 1 m 6 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 1 = 3.","cm는 cm끼리 빼요 — 29 − 6 = 23.","그래서 4 m 29 cm − 1 m 6 cm = 3 m 23 cm예요."],"options":[{"t":"3 m 23 cm","correct":true},{"t":"5 m 35 cm","mis":"M2-2-u3-X10"},{"t":"4 m 23 cm","mis":"M2-2-u3-X08"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#14','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],false,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 4 m는 1 m가 4번이니 2걸음씩 4번 — 2 + 2 + 2 + 2 = 8이에요.","그래서 약 8걸음쯤이에요."],"options":[{"t":"약 8걸음","correct":true},{"t":"약 6걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#15','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',2,'mc','auto','약 2 m를 어림한 것을 이용하여 5배 정도로 어림하면 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"약 2 m를 어림한 것을 이용하여 5배 정도로 어림하면 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 25 m","mis":"M2-2-u3-X14"}],"explanation":["5배 정도는 다섯 번이에요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 약 10 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#16','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',2,'ox','auto','멀리 던지기에서는 물체가 굴러가서 멈춘 곳까지 재요.',ARRAY['M2-2-u3-X20']::text[],false,'{"seq":16,"concept":"M2-2-u3-C4","difficulty":2,"kind":"ox","stem":"멀리 던지기에서는 물체가 굴러가서 멈춘 곳까지 재요.","answer":"X","reason_options":[{"t":"출발선에서 물체가 바닥에 떨어진 곳까지 곧게 재야 하니까","correct":true},{"t":"멈춘 곳까지 재야 더 멀리 던진 것이 되니까","mis":"M2-2-u3-X20"}],"mis":"M2-2-u3-X20","explanation":["멀리 던지기는 떨어진 곳까지 재요.","거리는 직선거리로 재요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#17','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',3,'mc','auto','알림판의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 알림판의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],false,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"알림판의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 알림판의 길이는 몇 cm인가요?","explanation":["알림판의 한끝은 눈금 3, 다른 끝은 눈금 123에 있어요.","123 − 3 = 120이니 120 cm예요.","끝 눈금 123을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"options":[{"t":"120 cm","correct":true},{"t":"123 cm","mis":"M2-2-u3-X06"},{"t":"121 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":120,"label":"알림판","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#18','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',3,'mc','auto','친구가 6 m 80 cm − 4 m 50 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X10']::text[],false,'{"seq":18,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 6 m 80 cm − 4 m 50 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?","options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"10 m 130 cm","mis":"M2-2-u3-X10"}],"explanation":["같은 단위끼리 줄을 맞추어 써요.","cm끼리 80 − 50 = 30, m끼리 6 − 4 = 2예요.","바른 답은 2 m 30 cm — 친구는 끝자리 0을 떼어 썼어요."],"asset":{"type":"mcm_calc","a":[6,80],"b":[4,50],"op":"-","ask":"both","said":[2,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#19','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',3,'mc','auto','352 cm, 3 m 25 cm, 3 m 40 cm 가운데 가장 짧은 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":19,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"352 cm, 3 m 25 cm, 3 m 40 cm 가운데 가장 짧은 것은 어느 것인가요?","options":[{"t":"3 m 25 cm","correct":true},{"t":"3 m 40 cm","mis":"M2-2-u3-X18"},{"t":"352 cm","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 352 cm, 325 cm, 340 cm예요.","325 cm가 가장 짧아요.","그래서 3 m 25 cm가 가장 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#20','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',3,'mc','auto','바다악어의 몸길이는 약 4 m 80 cm, 백상아리의 몸길이는 약 4 m 30 cm예요. 바다악어가 약 얼마나 더 긴가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다악어의 몸길이는 약 4 m 80 cm, 백상아리의 몸길이는 약 4 m 30 cm예요. 바다악어가 약 얼마나 더 긴가요?","options":[{"t":"약 50 cm","correct":true},{"t":"약 9 m 10 cm","mis":"M2-2-u3-X10"},{"t":"약 1 m 50 cm","mis":"M2-2-u3-X08"}],"explanation":["얼마나 더 긴지는 차로 구해요.","m끼리 4 − 4 = 0, cm끼리 80 − 30 = 50이에요.","그래서 약 50 cm 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#21','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범 약 1 m 80 cm, 돌고래 약 2 m 20 cm, 범고래 약 6 m 50 cm, 바다거북 약 1 m 30 cm, 바다악어 약 4 m 80 cm, 백상아리 약 4 m 30 cm 가운데 몸길이가 가장 긴 동물은 무엇인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X17']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범 약 1 m 80 cm, 돌고래 약 2 m 20 cm, 범고래 약 6 m 50 cm, 바다거북 약 1 m 30 cm, 바다악어 약 4 m 80 cm, 백상아리 약 4 m 30 cm 가운데 몸길이가 가장 긴 동물은 무엇인가요?","options":[{"t":"범고래","correct":true},{"t":"바다악어","mis":"M2-2-u3-X18"},{"t":"백상아리","mis":"M2-2-u3-X17"}],"explanation":["m의 수부터 견주어요.","6 m인 범고래가 가장 길어요.","cm의 수 80만 보고 바다악어를 고르면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#22','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',3,'mc','auto','운동장의 짧은 쪽에 나무가 약 2 m 간격으로 13그루 심어져 있어요. 운동장의 짧은 쪽 길이는 약 몇 m라고 어림할 수 있나요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"운동장의 짧은 쪽에 나무가 약 2 m 간격으로 13그루 심어져 있어요. 운동장의 짧은 쪽 길이는 약 몇 m라고 어림할 수 있나요?","options":[{"t":"약 24 m","correct":true},{"t":"약 26 m","mis":"M2-2-u3-X15"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["나무 13그루 사이의 간격은 12개예요.","약 2 m씩 12번이니 약 24 m예요.","나무 수만큼 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#23','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',4,'essay','teacher','5 m 64 cm − 3 m 22 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"5 m 64 cm − 3 m 22 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인해 보세요.","answer_guide":{"answer":"예: m끼리 5 − 3 = 2, cm끼리 64 − 22 = 42이므로 2 m 42 cm이다. 2 m 42 cm + 3 m 22 cm = 5 m 64 cm가 되어 맞다.","scoring_points":["2 m 42 cm를 구했는가","차에 뺀 길이를 더해 확인했는가","처음 길이가 나온다고 썼는가"]},"explanation":["m는 m끼리, cm는 cm끼리 빼요.","2 m 42 cm + 3 m 22 cm = 5 m 64 cm예요.","처음 길이가 나오면 맞게 계산한 거예요."],"asset":{"type":"mcm_calc","a":[5,64],"b":[3,22],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#24','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',4,'essay','teacher','바다표범(약 1 m 80 cm)과 돌고래(약 2 m 20 cm)의 몸길이를 바닥에 이어서 나타냈어요. 이은 길이를 구하고, cm끼리 더한 값이 100이 될 때 어떻게 했는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"바다표범(약 1 m 80 cm)과 돌고래(약 2 m 20 cm)의 몸길이를 바닥에 이어서 나타냈어요. 이은 길이를 구하고, cm끼리 더한 값이 100이 될 때 어떻게 했는지 설명해 보세요.","answer_guide":{"answer":"예: m끼리 1 + 2 = 3, cm끼리 80 + 20 = 100이다. 100 cm = 1 m이므로 3 m와 1 m를 모아 이은 길이는 약 4 m이다.","scoring_points":["m끼리·cm끼리 더했는가","100 cm = 1 m를 이용했는가","약 4 m를 구했는가"]},"explanation":["cm끼리 더하면 100 cm예요.","100 cm는 1 m예요.","그래서 이은 길이는 약 4 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_b#25','math',2,2,'u3','','tb_g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',4,'mc','auto','1 m가 약 2걸음인 친구가 운동장의 짧은 쪽(약 25 m)을 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],false,'{"seq":25,"concept":"M2-2-u3-C7","difficulty":4,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 운동장의 짧은 쪽(약 25 m)을 걸으면 몇 걸음쯤일까요?","options":[{"t":"약 50걸음","correct":true},{"t":"약 27걸음","mis":"M2-2-u3-X14"},{"t":"약 25걸음","mis":"M2-2-u3-X13"}],"explanation":["1 m가 약 2걸음이에요.","약 25 m는 1 m가 25번이니 2걸음씩 25번이에요.","25 + 25 = 50 — 약 50걸음쯤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#1','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C1',1,'sa','auto','600 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"600 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","600 cm는 100 cm가 6번이에요.","그래서 600 cm = 6 m예요."],"answer":["6"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#2','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',1,'sa','auto','3 m 52 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"3 m 52 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["3 m는 300 cm예요.","300 cm와 52 cm를 모으면 352 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"answer":["352"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#3','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',1,'mc','auto','책상의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],false,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"책상의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 140이니 140 cm예요.","140 cm = 100 cm + 40 cm = 1 m 40 cm예요."],"options":[{"t":"1 m 40 cm","correct":true},{"t":"14 m","mis":"M2-2-u3-X03"},{"t":"1 m 41 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":140,"label":"책상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#4','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',1,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 1 + 1 = 2.","cm는 cm끼리 더해요 — 70 + 20 = 90.","그래서 1 m 70 cm + 1 m 20 cm = 2 m 90 cm예요."],"options":[{"t":"2 m 90 cm","correct":true},{"t":"2 m 9 cm","mis":"M2-2-u3-X11"},{"t":"3 m 90 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[1,70],"b":[1,20],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#5','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',1,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 빼요 — 2 − 1 = 1.","cm는 cm끼리 빼요 — 50 − 40 = 10.","그래서 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요."],"options":[{"t":"1 m 10 cm","correct":true},{"t":"3 m 90 cm","mis":"M2-2-u3-X10"},{"t":"1 m 1 cm","mis":"M2-2-u3-X11"}],"asset":{"type":"mcm_calc","a":[2,50],"b":[1,40],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#6','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',1,'mc','auto','길이가 2 m 50 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 1 m 40 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"길이가 2 m 50 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 1 m 40 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?","options":[{"t":"1 m 10 cm","correct":true},{"t":"3 m 90 cm","mis":"M2-2-u3-X10"},{"t":"1 m 1 cm","mis":"M2-2-u3-X08"}],"explanation":["전체 막대에서 한 도막을 빼면 다른 도막이에요.","m끼리 2 − 1 = 1, cm끼리 50 − 40 = 10예요.","두 길이를 더하면 안 돼요 — 다른 도막은 1 m 10 cm예요."],"asset":{"type":"mbar","parts":[[2,50],[1,40]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#7','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',1,'mc','auto','두 깃발 사이가 약 5 m가 되도록 깃발 3개를 같은 간격으로 놓았어요. 첫 깃발과 마지막 깃발 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"두 깃발 사이가 약 5 m가 되도록 깃발 3개를 같은 간격으로 놓았어요. 첫 깃발과 마지막 깃발 사이의 거리는 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 15 m","mis":"M2-2-u3-X15"},{"t":"약 3 m","mis":"M2-2-u3-X15"}],"explanation":["깃발 3개 사이의 간격은 2개예요.","약 5 m씩 2번이니 약 10 m예요.","깃발 수만큼 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#8','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C7',1,'mc','auto','학교 시설물의 길이를 어림해요. 「칠판의 긴 쪽의 길이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"학교 시설물의 길이를 어림해요. 「칠판의 긴 쪽의 길이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?","options":[{"t":"3 m","correct":true},{"t":"3 cm","mis":"M2-2-u3-X17"},{"t":"30 m","mis":"M2-2-u3-X17"}],"explanation":["칠판의 긴 쪽은 양팔을 세 번쯤 벌린 길이예요.","1 m가 세 번이면 3 m예요.","그래서 약 3 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#9','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',2,'mc','auto','사물함의 길이는 5 m 20 cm, 알림판의 길이는 1 m 20 cm예요. 사물함이 얼마나 더 긴가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"사물함의 길이는 5 m 20 cm, 알림판의 길이는 1 m 20 cm예요. 사물함이 얼마나 더 긴가요?","options":[{"t":"4 m","correct":true},{"t":"6 m 40 cm","mis":"M2-2-u3-X10"},{"t":"4 m 20 cm","mis":"M2-2-u3-X08"}],"explanation":["얼마나 더 긴지는 차로 구해요.","m끼리 5 − 1 = 4, cm끼리 20 − 20 = 0이에요.","그래서 4 m 더 길어요 — cm가 0이면 m만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#10','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#11','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',2,'mc','auto','소파의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],false,'{"seq":11,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"소파의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["소파의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 250이니 250 cm예요.","250 cm = 200 cm + 50 cm = 2 m 50 cm예요."],"options":[{"t":"2 m 50 cm","correct":true},{"t":"25 m","mis":"M2-2-u3-X03"},{"t":"2 m 51 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":250,"label":"소파"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#12','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',2,'mc','auto','굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":12,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 7 = 12.","cm는 cm끼리 더해요 — 35 + 40 = 75.","그래서 5 m 35 cm + 7 m 40 cm = 12 m 75 cm예요."],"options":[{"t":"12 m 75 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"13 m 75 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#13','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',2,'mc','auto','두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09']::text[],false,'{"seq":13,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 9 − 1 = 8.","cm는 cm끼리 빼요 — 48 − 3 = 45.","그래서 9 m 48 cm − 1 m 3 cm = 8 m 45 cm예요."],"options":[{"t":"8 m 45 cm","correct":true},{"t":"10 m 51 cm","mis":"M2-2-u3-X10"},{"t":"8 m 18 cm","mis":"M2-2-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#14','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 7뼘인 친구가 끈 약 2 m를 뼘으로 재면 몇 뼘쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],false,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 7뼘인 친구가 끈 약 2 m를 뼘으로 재면 몇 뼘쯤일까요?","options":[{"t":"약 14뼘","correct":true},{"t":"약 9뼘","mis":"M2-2-u3-X14"},{"t":"약 2뼘","mis":"M2-2-u3-X13"}],"explanation":["1 m가 약 7뼘이에요.","약 2 m는 1 m가 2번이니 7 + 7 = 14예요.","그래서 약 14뼘쯤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#15','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',2,'mc','auto','운동장의 짧은 쪽을 약 10 m, 약 5 m, 약 10 m로 나누어 어림했어요. 전체 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"운동장의 짧은 쪽을 약 10 m, 약 5 m, 약 10 m로 나누어 어림했어요. 전체 거리는 약 몇 m인가요?","options":[{"t":"약 25 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X14"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 길이를 모두 더해요.","10 + 5 + 10 = 25예요.","그래서 약 25 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#16','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',2,'ox','auto','줄자는 팽팽하게 펴서 길이를 재요.',ARRAY['M2-2-u3-X20']::text[],false,'{"seq":16,"concept":"M2-2-u3-C4","difficulty":2,"kind":"ox","stem":"줄자는 팽팽하게 펴서 길이를 재요.","answer":"O","reason_options":[{"t":"줄자가 처지면 실제보다 길게 읽으니까","correct":true},{"t":"줄자는 느슨해도 눈금이 똑같으니까","mis":"M2-2-u3-X20"}],"mis":"M2-2-u3-X20","explanation":["줄자가 처지면 굽은 만큼 눈금이 더 나가요.","그래서 팽팽하게 펴서 재요.","바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#17','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',3,'mc','auto','소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],false,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요?","explanation":["소파의 한끝은 눈금 2, 다른 끝은 눈금 252에 있어요.","252 − 2 = 250이니 250 cm예요.","끝 눈금 252를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"options":[{"t":"250 cm","correct":true},{"t":"252 cm","mis":"M2-2-u3-X06"},{"t":"251 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":250,"label":"소파","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#18','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',3,'mc','auto','친구가 1 m 70 cm + 1 m 20 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X10']::text[],false,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 1 m 70 cm + 1 m 20 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?","options":[{"t":"2 m 90 cm","correct":true},{"t":"2 m 9 cm","mis":"M2-2-u3-X11"},{"t":"50 cm","mis":"M2-2-u3-X10"}],"explanation":["같은 단위끼리 줄을 맞추어 써요.","cm끼리 70 + 20 = 90, m끼리 1 + 1 = 2예요.","바른 답은 2 m 90 cm — 친구는 끝자리 0을 떼어 썼어요."],"asset":{"type":"mcm_calc","a":[1,70],"b":[1,20],"op":"+","ask":"both","said":[2,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#19','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',3,'mc','auto','573 cm, 5 m 64 cm, 5 m 35 cm 가운데 가장 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":19,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"573 cm, 5 m 64 cm, 5 m 35 cm 가운데 가장 긴 것은 어느 것인가요?","options":[{"t":"573 cm","correct":true},{"t":"5 m 64 cm","mis":"M2-2-u3-X18"},{"t":"5 m 35 cm","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 573 cm, 564 cm, 535 cm예요.","573 cm가 가장 길어요.","그래서 573 cm가 가장 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#20','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범(약 1 m 80 cm)과 돌고래(약 2 m 20 cm)의 몸길이를 바닥에 이어서 나타냈어요. 이은 길이는 약 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범(약 1 m 80 cm)과 돌고래(약 2 m 20 cm)의 몸길이를 바닥에 이어서 나타냈어요. 이은 길이는 약 얼마인가요?","options":[{"t":"약 4 m","correct":true},{"t":"약 60 cm","mis":"M2-2-u3-X10"},{"t":"약 3 m 100 cm","mis":"M2-2-u3-X08"}],"explanation":["m끼리 1 + 2 = 3, cm끼리 80 + 20 = 100이에요.","100 cm는 1 m — 3 m와 1 m를 모으면 4 m예요.","그래서 이은 길이는 약 4 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#21','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범 약 1 m 80 cm, 돌고래 약 2 m 20 cm, 범고래 약 6 m 50 cm, 바다거북 약 1 m 30 cm, 바다악어 약 4 m 80 cm, 백상아리 약 4 m 30 cm 가운데 몸길이가 가장 짧은 동물은 무엇인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X17']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범 약 1 m 80 cm, 돌고래 약 2 m 20 cm, 범고래 약 6 m 50 cm, 바다거북 약 1 m 30 cm, 바다악어 약 4 m 80 cm, 백상아리 약 4 m 30 cm 가운데 몸길이가 가장 짧은 동물은 무엇인가요?","options":[{"t":"바다거북","correct":true},{"t":"돌고래","mis":"M2-2-u3-X18"},{"t":"바다표범","mis":"M2-2-u3-X17"}],"explanation":["m의 수가 1인 바다표범과 바다거북이 가장 짧은 쪽이에요.","1 m끼리 cm를 견주면 30 cm < 80 cm예요.","cm의 수 20만 보고 돌고래를 고르면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#22','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',3,'mc','auto','운동장의 짧은 쪽에 거리 표시기 사이 간격 약 1 m가 25칸 있어요. 축구 골대의 긴 쪽(약 5 m)을 기준으로 하면 운동장의 짧은 쪽은 골대 몇 개 길이쯤인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"운동장의 짧은 쪽에 거리 표시기 사이 간격 약 1 m가 25칸 있어요. 축구 골대의 긴 쪽(약 5 m)을 기준으로 하면 운동장의 짧은 쪽은 골대 몇 개 길이쯤인가요?","options":[{"t":"5개","correct":true},{"t":"25개","mis":"M2-2-u3-X14"},{"t":"20개","mis":"M2-2-u3-X14"}],"explanation":["약 1 m가 25칸이니 약 25 m예요.","약 5 m가 5번이면 25 m예요.","그래서 골대 5개 길이쯤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#23','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',4,'essay','teacher','2 m 24 cm + 7 m 5 cm를 9 m 74 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"2 m 24 cm + 7 m 5 cm를 9 m 74 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 7 m 5 cm의 5를 50처럼 더해 24 + 50 = 74로 계산했다. cm끼리 24 + 5 = 29이므로 바른 답은 9 m 29 cm이다.","scoring_points":["5를 50으로 본 잘못을 찾았는가","cm끼리 24 + 5 = 29를 구했는가","9 m 29 cm라고 바르게 썼는가"]},"explanation":["7 m 5 cm의 cm는 5예요.","cm끼리 24 + 5 = 29예요.","바른 답은 9 m 29 cm예요."],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"both","said":[9,74]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#24','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',4,'essay','teacher','물에 사는 동물의 몸길이를 조사해 동물 카드에 적어요. 몸길이를 적을 때 조심할 점을 두 가지 쓰고, 바다악어의 카드를 바르게 적어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"물에 사는 동물의 몸길이를 조사해 동물 카드에 적어요. 몸길이를 적을 때 조심할 점을 두 가지 쓰고, 바다악어의 카드를 바르게 적어 보세요.","answer_guide":{"answer":"예: 몸길이에 단위(m, cm)를 꼭 붙인다. 몸길이가 자라는 범위로 나와 있으면 가장 길게 자라는 길이를 적고 「약」을 붙인다. 카드: 바다악어 — 몸길이 약 4 m 80 cm.","scoring_points":["단위를 붙인다고 썼는가","어림한(조사한) 길이에 「약」을 붙이거나 가장 긴 길이를 적는다고 썼는가","바다악어 약 4 m 80 cm를 바르게 적었는가"]},"explanation":["몸길이에는 단위를 붙여 「몇 m 몇 cm」로 적어요.","조사한 길이에는 「약」을 붙여요.","친구들의 카드를 모아 동물 몸길이 사전을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_c#25','math',2,2,'u3','','tb_g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',4,'mc','auto','두 나무 사이의 거리가 약 16 m, 그네의 길이가 약 4 m, 울타리 한 칸이 약 2 m예요. 그네 양쪽의 거리가 같다면 왼쪽 나무에서 그네까지 울타리는 몇 칸인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":25,"concept":"M2-2-u3-C8","difficulty":4,"kind":"mc","stem":"두 나무 사이의 거리가 약 16 m, 그네의 길이가 약 4 m, 울타리 한 칸이 약 2 m예요. 그네 양쪽의 거리가 같다면 왼쪽 나무에서 그네까지 울타리는 몇 칸인가요?","options":[{"t":"3칸","correct":true},{"t":"6칸","mis":"M2-2-u3-X14"},{"t":"8칸","mis":"M2-2-u3-X14"}],"explanation":["16 m에서 그네 4 m를 빼면 12 m, 한쪽은 6 m예요.","울타리 한 칸이 약 2 m이니 6 m는 3칸이에요.","2 + 2 + 2 = 6으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#1','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C1',1,'sa','auto','3 m는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"3 m는 몇 cm인가요? 숫자로 쓰세요.","explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번이에요.","그래서 3 m = 300 cm예요."],"answer":["300"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#2','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',1,'mc','auto','142 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],false,'{"seq":2,"concept":"M2-2-u3-C2","difficulty":1,"kind":"mc","stem":"142 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["142 cm는 100 cm와 42 cm예요.","100 cm는 1 m예요.","그래서 142 cm = 1 m 42 cm예요."],"options":[{"t":"1 m 42 cm","correct":true},{"t":"14 m 2 cm","mis":"M2-2-u3-X03"},{"t":"1 m 4 cm","mis":"M2-2-u3-X11"},{"t":"42 m 1 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#3','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',1,'sa','auto','알림판의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"알림판의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["알림판의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 120이니 120 cm예요.","120 cm는 1 m 20 cm라고도 나타내요."],"answer":["120"],"asset":{"type":"tape","len":120,"label":"알림판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#4','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',1,'mc','auto','3 m 40 cm + 5 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 40 cm + 5 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 40 + 50 = 90.","그래서 3 m 40 cm + 5 m 50 cm = 8 m 90 cm예요."],"options":[{"t":"8 m 90 cm","correct":true},{"t":"2 m 10 cm","mis":"M2-2-u3-X10"},{"t":"8 m 9 cm","mis":"M2-2-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#5','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',1,'mc','auto','6 m 80 cm − 4 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"6 m 80 cm − 4 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 80 − 50 = 30.","그래서 6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요."],"options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#6','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',1,'mc','auto','길이가 7 m 74 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 5 m 32 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"길이가 7 m 74 cm인 막대를 두 도막으로 잘랐어요. 한 도막의 길이가 5 m 32 cm일 때 다른 한 도막의 길이는 몇 m 몇 cm인가요?","options":[{"t":"2 m 42 cm","correct":true},{"t":"13 m 6 cm","mis":"M2-2-u3-X10"},{"t":"2 m 32 cm","mis":"M2-2-u3-X08"}],"explanation":["전체 막대에서 한 도막을 빼면 다른 도막이에요.","m끼리 7 − 5 = 2, cm끼리 74 − 32 = 42예요.","두 길이를 더하면 안 돼요 — 다른 도막은 2 m 42 cm예요."],"asset":{"type":"mbar","parts":[[7,74],[5,32]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#7','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',1,'mc','auto','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 8명이면 사이 간격은 7개예요.","약 1 m씩 7번이니 약 7 m예요.","사람 수만큼 8번 더하면 안 돼요 — 간격을 세어요."],"options":[{"t":"약 7 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#8','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C7',1,'mc','auto','학교 시설물의 길이를 어림해요. 「축구 골대의 긴 쪽의 길이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"학교 시설물의 길이를 어림해요. 「축구 골대의 긴 쪽의 길이는 약 ▢입니다.」에 알맞은 것은 어느 것인가요?","options":[{"t":"5 m","correct":true},{"t":"5 cm","mis":"M2-2-u3-X17"},{"t":"50 m","mis":"M2-2-u3-X17"}],"explanation":["축구 골대의 긴 쪽은 여러 사람이 나란히 설 만큼 길어요.","1 m를 다섯 번 이은 만큼이에요.","그래서 약 5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#9','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',2,'mc','auto','멀리 던지기에서 슬기는 배드민턴공을 3 m 50 cm, 종이컵을 3 m 30 cm 던졌어요. 배드민턴공을 얼마나 더 멀리 던졌나요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"멀리 던지기에서 슬기는 배드민턴공을 3 m 50 cm, 종이컵을 3 m 30 cm 던졌어요. 배드민턴공을 얼마나 더 멀리 던졌나요?","options":[{"t":"20 cm","correct":true},{"t":"6 m 80 cm","mis":"M2-2-u3-X10"},{"t":"1 m 20 cm","mis":"M2-2-u3-X08"}],"explanation":["얼마나 더 멀리 던졌는지는 차로 구해요.","m끼리 3 − 3 = 0, cm끼리 50 − 30 = 20이에요.","그래서 20 cm 더 멀리 던졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#10','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#11','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',2,'sa','auto','책상의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"책상의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 140이니 140 cm예요.","140 cm는 1 m 40 cm라고도 나타내요."],"answer":["140"],"asset":{"type":"tape","len":140,"label":"책상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#12','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',2,'mc','auto','11 m 35 cm + 7 m 23 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":12,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"11 m 35 cm + 7 m 23 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 11 + 7 = 18.","cm는 cm끼리 더해요 — 35 + 23 = 58.","그래서 11 m 35 cm + 7 m 23 cm = 18 m 58 cm예요."],"options":[{"t":"18 m 58 cm","correct":true},{"t":"4 m 12 cm","mis":"M2-2-u3-X10"},{"t":"19 m 58 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#13','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',2,'mc','auto','6 m 80 cm인 색 테이프에서 4 m 50 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],false,'{"seq":13,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"6 m 80 cm인 색 테이프에서 4 m 50 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 80 − 50 = 30.","그래서 6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요."],"options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[6,80],[4,50]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#14','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 2 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X13','M2-2-u3-X14']::text[],false,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 2 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 2 m는 1 m가 2번이니 2걸음씩 2번 — 2 + 2 = 4예요.","그래서 약 4걸음쯤이에요."],"options":[{"t":"약 4걸음","correct":true},{"t":"약 2걸음","mis":"M2-2-u3-X13"},{"t":"약 6걸음","mis":"M2-2-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#15','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',2,'mc','auto','「20 m도 어림해 볼까?」 — 약 10 m의 2배 정도면 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"「20 m도 어림해 볼까?」 — 약 10 m의 2배 정도면 약 몇 m인가요?","options":[{"t":"약 20 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X14"},{"t":"약 30 m","mis":"M2-2-u3-X14"}],"explanation":["2배 정도는 두 번이에요.","10 + 10 = 20이에요.","그래서 약 20 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#16','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',2,'ox','auto','둥근 나무의 둘레는 곧은자로 재야 해요.',ARRAY['M2-2-u3-X19']::text[],false,'{"seq":16,"concept":"M2-2-u3-C4","difficulty":2,"kind":"ox","stem":"둥근 나무의 둘레는 곧은자로 재야 해요.","answer":"X","reason_options":[{"t":"줄자는 휘어져서 둥근 나무의 둘레를 감아 잴 수 있으니까","correct":true},{"t":"둥근 것은 곧은자로만 잴 수 있으니까","mis":"M2-2-u3-X19"}],"mis":"M2-2-u3-X19","explanation":["곧은자는 휘지 않아요.","줄자는 둘레에 감아 잴 수 있어요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#17','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',3,'mc','auto','사물함의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 사물함의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],false,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"사물함의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 사물함의 길이는 몇 cm인가요?","explanation":["사물함의 한끝은 눈금 3, 다른 끝은 눈금 523에 있어요.","523 − 3 = 520이니 520 cm예요.","끝 눈금 523을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"options":[{"t":"520 cm","correct":true},{"t":"523 cm","mis":"M2-2-u3-X06"},{"t":"521 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#18','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',3,'mc','auto','친구가 9 m 48 cm − 1 m 3 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X10']::text[],false,'{"seq":18,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 9 m 48 cm − 1 m 3 cm를 세로셈으로 계산한 답(빨간 글씨)이 틀렸어요. 바르게 고친 답은 얼마인가요?","options":[{"t":"8 m 45 cm","correct":true},{"t":"8 m 18 cm","mis":"M2-2-u3-X09"},{"t":"10 m 51 cm","mis":"M2-2-u3-X10"}],"explanation":["같은 단위끼리 줄을 맞추어 써요.","cm끼리 48 − 3 = 45, m끼리 9 − 1 = 8예요.","바른 답은 8 m 45 cm — 친구는 한 자리 수 cm를 몇십처럼 계산했어요."],"asset":{"type":"mcm_calc","a":[9,48],"b":[1,3],"op":"-","ask":"both","said":[8,18]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#19','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',3,'mc','auto','180 cm, 1 m 70 cm, 1 m 90 cm 가운데 가장 짧은 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":19,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"180 cm, 1 m 70 cm, 1 m 90 cm 가운데 가장 짧은 것은 어느 것인가요?","options":[{"t":"1 m 70 cm","correct":true},{"t":"180 cm","mis":"M2-2-u3-X18"},{"t":"1 m 90 cm","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 180 cm, 170 cm, 190 cm예요.","170 cm가 가장 짧아요.","그래서 1 m 70 cm가 가장 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#20','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범의 몸길이는 약 1 m 80 cm, 바다거북의 몸길이는 약 1 m 30 cm예요. 바다표범이 약 얼마나 더 긴가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범의 몸길이는 약 1 m 80 cm, 바다거북의 몸길이는 약 1 m 30 cm예요. 바다표범이 약 얼마나 더 긴가요?","options":[{"t":"약 50 cm","correct":true},{"t":"약 3 m 10 cm","mis":"M2-2-u3-X10"},{"t":"약 1 m 50 cm","mis":"M2-2-u3-X08"}],"explanation":["얼마나 더 긴지는 차로 구해요.","m끼리 1 − 1 = 0, cm끼리 80 − 30 = 50이에요.","그래서 약 50 cm 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#21','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범 약 1 m 80 cm, 돌고래 약 2 m 20 cm, 범고래 약 6 m 50 cm, 바다거북 약 1 m 30 cm, 바다악어 약 4 m 80 cm, 백상아리 약 4 m 30 cm 가운데 몸길이가 4 m보다 긴 동물은 모두 몇 마리인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범 약 1 m 80 cm, 돌고래 약 2 m 20 cm, 범고래 약 6 m 50 cm, 바다거북 약 1 m 30 cm, 바다악어 약 4 m 80 cm, 백상아리 약 4 m 30 cm 가운데 몸길이가 4 m보다 긴 동물은 모두 몇 마리인가요?","options":[{"t":"3마리","correct":true},{"t":"2마리","mis":"M2-2-u3-X18"},{"t":"6마리","mis":"M2-2-u3-X16"}],"explanation":["m의 수가 4 이상이면서 4 m보다 긴 동물을 찾아요.","범고래, 바다악어, 백상아리 — 3마리예요.","4 m 30 cm도 4 m보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#22','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',3,'mc','auto','두 나무 사이의 거리는 약 16 m이고 그네의 길이는 약 4 m예요. 그네 양쪽의 거리가 같다면 왼쪽 나무에서 그네까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"두 나무 사이의 거리는 약 16 m이고 그네의 길이는 약 4 m예요. 그네 양쪽의 거리가 같다면 왼쪽 나무에서 그네까지는 약 몇 m인가요?","options":[{"t":"약 6 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X14"},{"t":"약 8 m","mis":"M2-2-u3-X14"}],"explanation":["16 m에서 그네 4 m를 빼면 12 m예요.","양쪽이 똑같으니 12 m를 둘로 나누면 6 m씩이에요.","6 + 4 + 6 = 16으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#23','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',4,'essay','teacher','11 m 35 cm + 7 m 23 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"11 m 35 cm + 7 m 23 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.","answer_guide":{"answer":"예: m는 m 아래, cm는 cm 아래에 맞추어 쓴다. cm끼리 35 + 23 = 58, m끼리 11 + 7 = 18이다. 두 길이의 합은 18 m 58 cm이다.","scoring_points":["같은 단위끼리 맞추어 쓴다고 했는가","cm끼리·m끼리 더했는가","18 m 58 cm라고 구했는가"]},"explanation":["길이가 10 m보다 길어져도 방법은 같아요.","cm끼리 58, m끼리 18이에요.","두 길이의 합은 18 m 58 cm예요."],"asset":{"type":"mcm_calc","a":[11,35],"b":[7,23],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#24','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',4,'essay','teacher','수찬이의 키는 1 m 20 cm예요. 범고래(약 6 m 50 cm)의 몸길이는 수찬이의 키로 몇 번쯤 되는지 어림하고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"수찬이의 키는 1 m 20 cm예요. 범고래(약 6 m 50 cm)의 몸길이는 수찬이의 키로 몇 번쯤 되는지 어림하고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 약 5번쯤이다. 1 m 20 cm를 5번 이으면 약 6 m이고, 범고래는 약 6 m 50 cm라서 5번보다 조금 더 길다.","scoring_points":["약 5번쯤이라고 어림했는가","1 m 20 cm를 여러 번 이어 견주었는가","어림한 결과에 「약」이나 「쯤」을 붙였는가"]},"explanation":["내 키를 기준으로 몇 번쯤인지 어림해요.","1 m 20 cm를 5번 이으면 약 6 m예요.","범고래는 그보다 조금 더 길어 약 5번쯤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u3_review_d#25','math',2,2,'u3','','tb_g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',4,'mc','auto','약 25 m인 운동장의 짧은 쪽을 따라 약 5 m마다 깃발을 꽂아요. 처음과 끝에도 꽂으면 깃발은 몇 개 있어야 하나요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":25,"concept":"M2-2-u3-C8","difficulty":4,"kind":"mc","stem":"약 25 m인 운동장의 짧은 쪽을 따라 약 5 m마다 깃발을 꽂아요. 처음과 끝에도 꽂으면 깃발은 몇 개 있어야 하나요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M2-2-u3-X15"},{"t":"4개","mis":"M2-2-u3-X15"}],"explanation":["약 25 m에 약 5 m 간격은 5개예요.","처음과 끝에도 꽂으면 깃발은 간격보다 하나 많아요.","그래서 5 + 1 = 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
